window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_036"]={"n":"薛瑄","dyn":"明","poems":[{"t":"拟古四十一首 其二十","f":"五言古诗","c":["白云在高丘，绿萝在深谷。","中有冥栖士，云萝蔽茅屋。","独抱尚友情，缅遂硕人轴。","古琴时复弹，古书还更读。","逍遥无外事，俯仰长自足。","沮溺耕在野，姜叟钓渭曲。","伊人岂无心，耻衒荆山玉。","将须凤来仪，朝阳满梧竹。"]},{"t":"拟古四十一首 其三十九","f":"五言古诗","c":["庭树微飘落，凉气始披拂。","却忆少年时，泛舟湖湘曲。","秋风起波澜，寒霜下林麓。","日出江上枫，雾隐楚岸竹。","兰芷亦萧条，芰荷不秋馥。","灵均旧游处，骚思方满目。","忽忽三十年，凉意复相触。","《九歌》有遗辞，得意在云谷。"]},{"t":"秋思二首 其一","f":"五言律诗","c":["秋来何所思？","所思在远道。","洞庭木叶霜，楚泽芙蓉老。","欲济怀方舟，风波殊浩浩。","寄言双白鹤，尔来苦不早。"]},{"t":"秋思二首 其二","f":"五言古诗","c":["登高望沧海，长风欻来过。","九鳌互低昂，三山郁嵯峨。","绰约众仙子，飘飘戏其阿。","手把珊瑚枝，笑拂扶桑柯。","我欲往从之，道远百怪多。","安得骑鸿鹄，乘风越洪波。","举鞭逐蛟蜃，仗剑驱鼋鼍。","永与众仙会，遨游养天和。"]},{"t":"龙阳山行遇雨","f":"五言古诗","c":["岁晚山行深，山中水重叠。","丛篁夹溪桥，桥断横槎接。","阴雨竟连朝，云林黯一色。","虚风忽冷然，萧萧坠黄叶。","抚景复何为，内顾远游客。"]},{"t":"泊舟贻溪宿阳楼山下","f":"五言古诗","c":["窈窕入清溪，侧径何纡曲。","鱼梁截奔流，雪濑漱寒玉。","空翠湿人衣，雾雨满新竹。","路穷上野航，前登得平陆。","日暮烟火迷，似向桃源宿。"]},{"t":"平沙落雁","f":"五言古诗","c":["霜清秋水落，风过人迹平。","飞飞随阳鸟，相呼下寒汀。","向夕聚俦侣，月映芦花明。"]},{"t":"烟寺晚钟","f":"五言古诗","c":["夕照下山门，清音出烟雾。","暝壑一僧还，侧伫寻归路。","月上楚天宽，露落洞庭树。"]},{"t":"潇湘夜雨","f":"五言古诗","c":["两岸丛篁湿，一夕波浪生。","孤灯蓬底宿，江雨蓬背鸣。","南来北往客，同听不同情。"]},{"t":"江村暮雪","f":"五言古诗","c":["落落渔樵家，苍苍起烟雾。","岸滑移钓舟，沙平失归路。","似有凌波人，盈盈月中去。"]},{"t":"渔村落照","f":"五言古诗","c":["钓艇收晚缗，归鸦集疏柳。","天风吹彩霞，明月映江口。","孤村一笛横，万虑复何有。"]},{"t":"渡双溪","f":"五言古诗","c":["双溪始合流，崖绪遂经复。","洄潭一镜平，秋影空寒绿。","野渡得孤航，山家带乔木。","适意方自兹，前呵戒僮仆。","抚景重悠然，谁能和斯曲。"]},{"t":"湘江舟中","f":"五言古诗","c":["湛湛湘水绿，夹岸丛篁多。","挽舟逆水上，南风起微波。","嘉此晴霄景，逍遥玩江沱。","沙渚旷缅邈，云岫纷嵯峨。","远目为舒畅，客意将如何。","濯缨吾所爱，聊为扣舷歌。"]},{"t":"游君山寺","f":"五言古诗","c":["为爱湖中山，遂寻山下路。","跻攀转出邃，涧谷亦回互。","石磴足莓苔，青林杂烟雾。","前行如有穷，岚岭乍分布。","招提压重湖，千里周一顾。","孤峰四无根，形气自依附。","山僧复导我，窈窕更徐步。","疏篱野蔓悬，老圃寒泉注。","径转山房深，重与绝境遇。","白云檐外生，清风竹间度。","庭花杂无名，岁晏色犹故。","澄心得妙观，忘言契良晤。","爱此林壑清，遂薄尘俗务。","重来待何时，尚子毕嫁娶。"]},{"t":"洞庭遇雨","f":"五言律诗","c":["孤舟行何迟，岁晚洞庭雨。","跳波乱明珠，随风扬细缕。","云雾失君山，波浪连吴楚。","莫唱斑竹枝，别思满南浦。"]},{"t":"过鹿门山","f":"七言律诗","c":["西来汉水浸山根，舟人云此是鹿门。","峭壁苍苍石色古，曲径杳杳藤萝昏。","乱峰幽谷不知数，底是庞公栖隐处。","含情一啸江风清，双橹急摇下滩去。"]},{"t":"武口守风四首 其一","f":"五言律诗","c":["连日北风疾，江涛拍岸鸣。","天垂平野月，浪飐近船灯。","湖与归心阔，秋因客思清。","不眠听鼓角，高枕念王程。"]},{"t":"武陵晓泛","f":"五言律诗","c":["今朝风日好，来泛武陵溪。","碧水寒依岸，苍林远护堤。","沙光摇野鸟，人语散凫鹥。","二月桃花发，还应处处迷。"]},{"t":"荥阳咏古八首 其五","f":"七言律诗","c":["萧萧凉吹动秋空，千古河山一望中。","广武连营秋草碧，鸿沟分壤夕阳红。","石麟有甲含苍藓，铁马无声散晓风。","何限英豪俱泯灭，白云依旧出层峰。"]},{"t":"沅州杂诗十二首 其十二","f":"七言律诗","c":["辰沅风壤带三苗，一望乾坤吐纳遥。","翼轸众星朝北极，岷嶓诸岭导南条。","天邻巫峡常多雨，江过浔阳始有潮。","近日诗怀殊浩渺，谩将新句写芭蕉。"]},{"t":"戏题红白二梅花落","f":"五言古诗","c":["檐外双梅树，庭前昨夜风。","新英兼旧蕊，坠粉间飘红。","已见苔成锦，方疑色是空。","妆娥初点额，舞女欲迷踪。","雨重胭脂湿，泥香瑞雪融。","不知何处笛，并起一声中。"]},{"t":"夏日出文明门","f":"七言绝句","c":["文明门外柳阴阴，百啭黄鹂送好音。","行过御沟回望处，凤凰楼阁五云深。"]},{"t":"新郑学宫夜宿","f":"七言绝句","c":["清飙槭槭响林柯，夜宿秋堂冷簟波。","睡醒不禁乡思切，满庭明月候虫多。"]},{"t":"巩洛道中","f":"七言绝句","c":["嵩高云气晚嵯峨，清洛西风咽急波。","水色山光浑似旧，宋家陵墓夕阳多。"]},{"t":"穆陵关夜雨","f":"五言绝句","c":["暝色来远谷，清风动华烛。","山楼雨声寒，罗帷人独宿。"]},{"t":"山行 其一","f":"五言绝句","c":["山鸟多清音，山花有异香。","但得山间趣，宁辞山路长。"]},{"t":"山行 其二","f":"五言绝句","c":["荒冈断复连，风叶散还集。","霜落秋涧清，烟横晚岫碧。"]},{"t":"作息吟","f":"五言绝句","c":["向晚群动息，向晓群动作。","群动作息间，乃是先天学。"]},{"t":"东平行台有竹翳于恶木荒草命仆芟治嘉植乃遂诗以纪之","f":"五言古诗","c":["生平苦爱竹，义若君子交。","兹轩忽见之，俄顷漆在胶。","振衣步其下，周览增郁陶。","恶木一何多，蔓草一何饶。","翳此破苔笋，挠彼凌云梢。","命仆恣剪伐，得辞斤斧劳。","除恶贵绝本，蕴崇及沟壕。","荒秽既了了，凉风亦萧萧。","修茎遂生植，嘉荫惬游遨。","作诗纪颠末，庶为同心谣。"]},{"t":"穆陵关","f":"五言古诗","c":["危哉穆陵关，高出众山顶。","地势愈觉宽，天宇相回迥。","林木何萧森，首夏风色冷。","山楼试一登，眺览恣遐骋。","沂岱环西阴，淮海接南岭。","齐州走北川，扶桑控东影。","道里会一门，山川挈要领。","缅思千古前，豪伯互吞并。","齐履空复然，秦蚕已侵境。","干戈被长峦，生民困鱼鼎。","于今天道旋，四裔守安静。","山行昼落然，水宿夜无警。","顾我观风人，符节得屡秉。","作诗纪兹行，传与山将永。"]},{"t":"兰陵怀古","f":"五言古诗","c":["早发郯子国，午至兰陵邑。","兰陵久已荒，禾黍带荆棘。","惟有古寺存，径入林影密。","老僧知我来，出门远候立。","下马问往事，为我指遗迹。","苍茫古城东，墓有荀卿石。","我欲往寻之，还为野水隔。","忆昔周室卑，蛮荆凌上国。","兹邑乃其疆，人物殊烜赫。","寂寞千载馀，浮云空古色。","如何当日贤，重有逃䜛责。","只今文字存，尚为人指摘。","鞭马舍之去，极目远天碧。"]},{"t":"敬吟","f":"五言古诗","c":["人惟肖天地，亦具天地性。","性无物不存，存性惟一敬。","心敬体不偏，情敬发必中。","头敬形端直，鼻敬气肃静。","目敬无邪视，耳敬无妄听。","口敬不妄言，身敬不妄动。","手敬容必恭，足敬容必重。","瞬息敬存身，早作敬致用。","致用在天伦，天伦敬斯定。","夫敬必先义，妇敬必从令。","子敬孝必隆，父敬恩必盛。","臣敬百职修，君敬万邦靖。","兄敬笃其爱，弟敬谨其行。","朋友以敬交，然诺必重应。","敬则伦理明，不敬百行病。","仰惟古圣人，一敬更相命。","尧钦帝之宗，舜恭明两并。","祗台念禹德，日跻有汤圣。","文王安敬止，武王勉敬胜。","笃敬传孔业，敬德著周政。","敬惟群圣枢，大训迭辉映。","下逮河洛儒，绍统开迷径。","整肃严堤防，主一谨操柄。","惺惺不昏昧，收敛无馀剩。","用力在斯须，百体孰敢横。","圣途渐可登，圣言良可證。","一敬苟不存，万欲皆奔纵。","身心坠卑污，纲常灭天正。","禽兽将同归，人类孰与共。","噫嘻敬怠间，狂圣越天阱。","法言述圣谟，匪曰小子佞。"]},{"t":"送杨参议三首 其一 分韵得红字","f":"五言古诗","c":["白露下将夕，天宇生凉风。","之子有所适，告别何匆匆。","群公尽祖送，飞盖凌长空。","停骖泺水曲，列宴历亭中。","秋容澹觞酌，高风急丝桐。","酒尽俨将发，斑马何玲珑。","行当释尘鞅，还应挂飞篷。","大江转吴楚，重山入天丛。","锦城有佳色，浣溪有遗踪。","访古遂舒啸，观风足从容。","坐令全蜀俗，解与邹鲁同。","兹游岂云易，两情若为通。","翘首迟归雁，应是春花红。"]},{"t":"送杨参议三首 其二 分韵得露字","f":"五言律诗","c":["林木生凉飙，皋兰被清露。","念子三川行，正值九秋暮。","天空一雁翔，江远孤舟骛。","旬宣有佳兴，载咏甘棠句。"]},{"t":"送杨参议三首 其三 分韵得驿字","f":"五言律诗","c":["岷江泻东溟，岷山倚西极。","江山古名秀，杨君将此适。","秋风送征帆，夜火明水驿。","相忆瑶华音，看取东飞翼。"]},{"t":"友鹤轩","f":"五言古诗","c":["九皋阻且深，洁白有佳鸟。","中宵忽长鸣，清响彻四表。","开轩一听之，众理悉明了。","蚌蛤藏洪渊，秀气浮浩溔。","良璞在昆冈，清辉散岩㟽。","雅兴与兹同，至德潜且皎。","温温圣者孙，大道思远绍。","友鹤名华轩，存诚绝外扰。","水积成川流，水壅盛颠杪。","功深效岂彻，响大声不小。","惭非风雅才，作诗心自剽。"]},{"t":"冬夜怀魏希文","f":"五言古诗","c":["冬夜气何厉，冰雪辉前楹。","单居不能寐，怀我旧友生。","行云去不息，宾鸿各时征。","两情旷难合，欲语谁当听。","惟有寒月光，见予心宇清。","展转遂至旦，远思徒营营。"]},{"t":"荅仰宗岱寺丞见贻韵","f":"五言古诗","c":["念子青云器，早涉青云路。","行行捧德音，眷言省民务。","风俗广咨询，幽隐亟告诉。","来为人所悦，去为人所慕。","皇泽一以敷，郡国足膏澍。","况复崇文儒，士林喜披雾。","心涵玉壶冰，气袅金茎露。","怀哉明盛时，展矣风云遇。","而我同官良，惟子荷与顾。","通籍来旬宣，各自植嘉誉。","独有兰臭言，祗以同心故。","还应笃忠良，更此写中素。","何当展良觌，相期在秋暮。"]},{"t":"题陈希夷图","f":"五言古诗","c":["三峰亦何峻，白云亦何多。","中有高世士，冥栖掩松萝。","石泉漱寒玉，好鸟间青歌。","歌长一披拂，红紫争纷罗。","山隔五季尘，年颓万里波。","岂无经济策，肥遁矢靡他。","威凤不浪集，冥鸿难重过。","清心探化机，瞑目养天和。","真息深在踵，利贞静不讹。","只疑龙蛇蛰，不管岁月梭。","我欲升玉井，濯手攀嵯峨。","扣关起公语，妙理应如何。","欲去还自休，马图今在河。"]},{"t":"永慕堂为杨大参赋","f":"五言古诗","c":["大化运不息，逝水无停时。","依依旧居室，恻怆中肠悲。","书残读遗编，机有馀断丝。","斑衣不再舞，寿觞宁重持。","庭前百卉芳，但觉阴阳移。","仪容切寤寐，恍惚如见之。","亲心我所安，亲志我所期。","心志著且存，大节矢靡亏。","悠哉孝子情，勖此终天思。"]},{"t":"游禹门","f":"五言古诗","c":["春泽周四野，閒情乐时和。","出郊纵逸兴，缅怀佳山河。","禹门忽在望，峭壁云嵯峨。","石磴接飞栈，危楼架洪波。","空山响丝竹，虚堂进舞歌。","父老诚苦心，旨酒神所呵。","由来非一朝，吾意其如何。"]},{"t":"河汾五贤咏五首 其一 卜子夏","f":"五言古诗","c":["浩浩西河流，遥遥东鲁山。","山河远相隔，千里独游还。","升堂奥可入，岂曰文辞观。","相从陈蔡厄，松柏知天寒。","索居晚归来，侯国师甘盘。","去之几千载，高风洒尘寰。","瞻望不可及，青云映西关。"]},{"t":"河汾五贤咏五首 其二 段干木","f":"五言古诗","c":["冥鸿不受弋，神龙不可羁。","所以高世士，孤情薄云霓。","矫矫段干木，志节一何奇。","圭组岂其愿，轩冕不吾希。","踰垣犹弗见，况乃趋走之。","岂徒侯国尊，凛为百世师。"]},{"t":"河汾五贤咏五首 其三 文中子","f":"五言古诗","c":["古人不可见，古俗宁复淳。","依依万春乡，疏属连清汾。","良时旷莫与，鸣鸟寂不闻。","悠悠礼乐志，终与麋鹿群。","颓波逝东极，寒云满西津。","惜哉经世言，淆杂多芜榛。","时无伊川子，此意将谁论。"]},{"t":"河汾五贤咏五首 其四 太史公","f":"五言古诗","c":["爱有所见忘，忠有所见疑。","古来非一朝，人道每如兹。","悠悠太史公，言论适有期。","谓必情可白，宁知事参差。","奇文虽自解，骤骥谅难追。","巷伯彼何人，千载存其诗。"]},{"t":"河汾五贤咏五首 其五 东皋子","f":"五言古诗","c":["人仕为其名，子仕独为酒。","一斗众所称，五斗吾自取。","犹嫌酒未足，弃官归陇亩。","葛巾耕东皋，烟雨牛一耦。","种黍学陶翁，自酿还给口。","沈饮得真味，万事亦何有。","清风千载馀，谁复尚能友。"]},{"t":"古诗","f":"五言古诗","c":["天地常不没，山河镇如斯。","惟有人与物，代谢无停时。","因过咸秦境，周览生悲思。","渭水自萦带，南山亦参差。","兹惟帝王宅，自古称雄奇。","当时宫阙壮，摩霄切云霓。","千门与万户，珠帘锦绣帷。","一朝时事去，扫地无复遗。","城市尽为墟，麦秀草离离。","亦有英雄辈，干戈互相持。","慷慨争土疆，终老志不衰。","只今但丘冢，名姓宁可知。","京都足妖冶，高门富姜姬。","绰约姑射仙，鬒发冰雪肌。","只今化为土，况乃粉黛施。","休明盛文物，旗常画蛇龟。","千乘及万骑，杂遝相追随。","将相立轩冕，声乐奏英池。","繁华有万端，一去不可追。","俯仰千古事，有若梦幻为。","往者既已然，将来复如之。","寄语执迷子，当以理自推。"]},{"t":"浩叹","f":"五言古诗","c":["浩叹复浩叹，宁知亲眼见。","相彼天雨雪，必有先集霰。","蚁穴不知防，鲸波今汗漫。","君子虑兢危，小人尚欺诞。","已矣无与言，归去耕吾畔。"]},{"t":"泸川古意","f":"五言古诗","c":["三蜀古名郡，泸川古名州。","我来值残暑，偶此数日留。","新秋忽改节，凉风渐飕飗。","逍遥散前除，仰视天宇周。","征鸟去不息，白云亦悠悠。","佳人渺何许，重林蔽层丘。","秋日复西迈，大江自东流。","良辰不我与，古道旷莫酬。","愿闻瑶华音，行矣旋吾辀。"]},{"t":"五盘山","f":"五言古诗","c":["五盘何艰哉，石磴绕山腹。","诘屈入云霞，回互下崖谷。","嗟彼远道人，陟降劳筋骨。","跋马登层巅，悠然注远目。","惟见山色高，似觉地势促。","蜀道古艰险，兹险甲西蜀。","忆我去春来，山山正芬馥。","今夏喜北归，四月暑未燠。","兹山得再过，颇快登览欲。","前驿望黄坝，苍苍但云木。"]},{"t":"登金牛驿楼","f":"五言古诗","c":["好山四巃嵷，汉水前萦绕。","小楼试一登，山水青未了。","因思大禹时，洪流方浩渺。","乃竭胼胝劳，神功弥八表。","岷山在经纪，岷江亦疏导。","贡赋分九州，梁州已通道。","世传金牛诞，曾不细搜讨。","山驿赋短章，将为愚者晓。"]},{"t":"七盘道中","f":"五言古诗","c":["晓度七盘山，北行道弥恶。","峭壁根虚无，危栈架飞阁。","飘飘风吹衣，漠漠云涨壑。","下有黑龙江，乱石何磊落。","急濑转雷毂，奔湍散流沫。","洄潭更阴沉，俯视诚可愕。","兹路属再来，即事情已昨。","艰险难具论，惟与存颠末。"]},{"t":"褒斜道中","f":"五言古诗","c":["褒斜一何长，深谷自迤逦。","云木青无边，群峰各峻峙。","鸟道缘崖巅，危栈架江涘。","冥冥叫子规，决决响溪水。","累日山峡中，陟降亦劳只。","古来蜀道难，此道难莫儗。","自我入蜀门，今已一年矣。","既乏督办能，兼负素餐耻。","而况鬓发苍，胡宁不知止。","上章乞解绶，诏许感不已。","虽云此谷险，且遂北归喜。","行色宣柔毫，庶用传孙子。"]},{"t":"远道","f":"五言古诗","c":["远道复远道，驱驰何草草。","及归已踰年，白发添不少。","入门悼先亡，痛哭伤怀抱。","子妇共号咷，百感相煎煼。","拭泪问里闾，叹逝惊莫保。","衰杀谁使然，矫首问苍昊。","从此甘息机，田野安吾老。"]},{"t":"盂城驿雪中咏竹","f":"五言古诗","c":["高沙有候馆，阑槛殊幽清。","槛内足凡木，凋萎不可名。","独彼凌云竹，郁有冒雪青。","飘萧散寒叶，修直摇苍茎。","灵籁奏清响，锵若金石鸣。","晴霄吐华月，流影乱虚明。","赏玩竟朝夕，似当西南朋。","乃知岁寒操，匪独松柏贞。","矢心又不如，愧我为物灵。"]},{"t":"徐州洪","f":"五言古诗","c":["乱石何巉岩，长堤更宛转。","狭岸忽陡起，急濑如注坂。","回旋聚流沫，骇浪洒雪霰。","舟行良已难，下上劳拽挽。","翻思游川峡，江石尤险远。","瞿塘十二滩，波浪激雷电。","回视过兹洪，反若历平坦。","乃知所观大，小者不挂眼。"]},{"t":"淮南讴","f":"五言古诗","c":["淮土何漫漫，淮水自悠悠。","小山去已久，桂树遗岩幽。","昔有学仙子，意欲仍丹丘。","秋石既烹炼，鸿宝亦藏收。","鸡犬竟莫闻，行云去难留。","宁虑时事异，翻结千古愁。","舞榭荆棘生，歌台麋鹿游。","信知希世事，伊岂望外求。","揖让有尧舜，高风想巢由。","此道久已非，听我淮南讴。"]},{"t":"高邮冰泮发舟","f":"五言古诗","c":["晚泊高邮城，雨雪竟连日。","念彼役人劳，寓此盂城驿。","扁舟候晴发，河冰复鳞积。","因之累宿留，令我心悁悒。","忽报寒冱解，喜泛春流碧。","直过大江东，此地成追忆。"]},{"t":"冰解舟发","f":"五言古诗","c":["春冰涣然释，春流复溶溶。","解缆盂城驿，百尺牵东风。","连翩大舸来，峨峨挂飞篷。","登舻恣春览，烟华正濛濛。","泽国旷无际，重湖渺难穷。","渐觉高邮北，行及广陵东。","所过足清眺，舟人莫匆匆。"]},{"t":"出自城北门","f":"五言古诗","c":["出自城北门，周览快心目。","峨峨钟阜青，漫漫平湖绿。","木依长堤茂，树隐芳洲曲。","缥缈天际楼，高下林间屋。","遥遥江上山，连连远岫出。","江山自雄奇，帝里在经复。","佳丽从古然，嘉气方葱郁。","官署何岩岩，列宇面山麓。","偶兹吏隐兼，颇遂萧散欲。","超哉复超哉，白云自相逐。"]},{"t":"晚翠亭为张司徒作","f":"五言古诗","c":["花木何纷然，各竞芳菲时。","一夕下霜霰，憔悴无故姿。","严严司徒府，后圃殊逦迤。","而于岁寒日，挺此万竹枝。","群芳尽摇落，兹物独见奇。","密叶既不凋，劲节亦不移。","一径入深处，横桥夹清池。","池亭昼虚敞，宴坐生寒飔。","清影落四檐，静与秀色宜。","适契君子节，贞固老不衰。","为取亭中琴，弦我晚翠诗。"]},{"t":"澹庵卷为谢侍郎乃兄题","f":"五言古诗","c":["闽山何岧峣，闽水亦清泚。","中有肥遁人，雅志丘壑美。","山田入云耕，结屋傍流水。","耕稼有馀閒，琴书时复理。","寄兴槁梧中，游心竹素里。","庭户无嚣尘，外物绝珍绮。","疏食足充餐，絺布良适体。","朋来无杂言，谈道而已矣。","至乐既无假，浮荣焉足拟。","所以忘岁年，足不至州里。","白云在高丘，鸣鹤在中沚。","安得蹑轻风，一访澹庵子。"]},{"t":"拟古四十一首 其一","f":"五言古诗","c":["天地形之大，阴阳气之尊。","伊谁知此物，来自无极门。","清浊既莫离，动静互为根。","大化去不息，至理亦长存。","彼哉虚寂子，已矣无复论。"]},{"t":"拟古四十一首 其二","f":"五言古诗","c":["悠悠复悠悠，水中有行舟。","四序无淹晷，代谢不可留。","春鸟寂无声，寒蝉号素秋。","落叶满阡陌，白云散岩幽。","去去莫复道，颍阳有遗老。"]},{"t":"拟古四十一首 其三","f":"五言律诗","c":["庭前桂花发，清香散凉飔。","采采黄金英，倾筐方自持。","思欲赠远人，风波阻长岐。","望望不可反，馨洁空自奇。"]},{"t":"拟古四十一首 其四","f":"五言律诗","c":["吾思古圣心，迥出八纮表。","天理为之大，人世为之小。","尧虞禹相授，杯水拱揖了。","终古骇其事，未足称达道。"]},{"t":"拟古四十一首 其五","f":"五言古诗","c":["四时一何神，变化不可测。","阴阳既交代，星辰递罗列。","孰其主宰之，终古不差忒。","圣人秉明灵，动息有贞则。","吾慕鲁中叟，矢心以学易。"]},{"t":"拟古四十一首 其六","f":"五言古诗","c":["端居忆远游，路经首阳山。","山有二贤祠，青松荫重关。","斯人难再得，守饿心独安。","清风激颓俗，高义越人寰。","去之几千载，可慕不可攀。"]},{"t":"拟古四十一首 其七","f":"五言古诗","c":["驺虞兽之瑞，麒麟兽之仁。","物性尚不杀，而况形为人。","夫何周辙东，王道久已湮。","孙吴骋狙诈，申商号无恩。","流毒剧洪水，遗黎苦漂沦。","强嬴灭诸国，三户亡咸秦。","天道信反覆，永为来世陈。"]},{"t":"拟古四十一首 其八","f":"五言古诗","c":["圣治奠九有，禹迹亦茫茫。","王泽既饶洽，彝伦复昭彰。","以兹熙皞世，举俗跻乐康。","胡为古道非，极意开边荒。","征行苦锋镝，飞挽失耕桑。","民生既骚屑，天和亦乖伤。","广土竟何益，不救危与亡。","兹事已千载，雄豪有秦皇。"]},{"t":"拟古四十一首 其九","f":"五言古诗","c":["荆山有美璞，巴蜀多名材。","此物信为奇，攻治亦难哉。","匠石得其良，宝就成层台。","胡为用匪人，坐此斲削乖。","既自玉之玷，还为木之灾。","而况上天工，理代必汝谐。","餗覆良可虑，栋挠谅难陪。","所以虞周圣，登庸必贤材。"]},{"t":"拟古四十一首 其十","f":"五言古诗","c":["湖边多杨柳，山上多松柏。","松柏存正性，不改青青色。","杨柳易为春，随风发枝节。","二月丝垂金，三月絮飞雪。","纷纷冶游子，赏玩不知歇。","松柏寂无言，枝干独挺特。","空以木自奇，不为时所悦。","请看霜霰馀，荣悴居然别。"]},{"t":"拟古四十一首 其十一","f":"五言古诗","c":["时来行堤上，春气薰人心。","宛转湖山曲，隐映花树林。","芊绵草抽绿，蒙茸柳垂金。","鸣鸟何间关，纤鳞或浮沈。","生物方总总，大化亦骎骎。","当时浴沂者，乐意不可寻。"]},{"t":"拟古四十一首 其十二","f":"五言古诗","c":["混沌鸿濛中，伊谁作主尸。","洪河出龙马，清洛浮神龟。","有文粲以别，实惟天所为。","悟彼阴与阳，契此偶将奇。","大圣发深智，运意画两仪。","生生之谓易，变化无崖涯。","宇宙岂云大，弥纶靡有遗。","如何千载馀，图象閟莫知。","卓哉弄丸子，探源溯希夷。","从兹识姬孔，还应见伏羲。","伊闽有遗编，学易真吾师。"]},{"t":"拟古四十一首 其十三","f":"五言古诗","c":["灼灼春庭树，开花渐离披。","因思唐虞世，日方亭午时。","大禹亦神圣，兢兢为保持。","如何百代下，此道久已衰。","丰亨王格之，请看大易辞。"]},{"t":"拟古四十一首 其十四","f":"五言古诗","c":["木腐虫蠹出，气乖疣赘生。","曜灵一薄蚀，阴曀郁然兴。","道术裂周季，纵横乱秦嬴。","青牛既夙驾，白马亦时征。","汜滥自涓滴，熺赫兆星星。","多谢宋诸老，万古开昏冥。","如何阳光发，尚自爝火明。","寄语行路人，勿迷棘与荆。"]},{"t":"拟古四十一首 其十五","f":"五言古诗","c":["萋萋湖边草，荣荣山上花。","山中有高士，探化心靡他。","天地自橐籥，万物从交加。","深居不窥牖，四海皆森罗。","我欲见其人，扪萝陟山阿。","山阿忽回合，冥蒙起烟霞。","至道复谁语，奈此高士何。"]},{"t":"拟古四十一首 其十六","f":"五言古诗","c":["太虚浩无际，何所立天堂。","坤厚大气举，地狱置何方。","此理亦昭哉，妄见胡冥茫。","万世为之惑，福果侥难量。","高标拔地起，飞宇就天翔。","抟刻土木梗，镕剂金银妆。","人力为殚竭，财物亦耗伤。","既自息吹乖，焉得寒暑常。","兹事自前季，滔天势弥张。","反经如可作，兴言讨彼狂。"]},{"t":"拟古四十一首 其十七","f":"五言古诗","c":["圆象无停运，大化不可留。","征车既西迈，行舟复东流。","辙迹苦相背，两美焉得由。","青松生涧底，白日丽高丘。","馀光不回照，直干空萧飕。","去去莫复道，零露满春草。"]},{"t":"拟古四十一首 其十八","f":"五言古诗","c":["五陵多侠客，三辅足贵豪。","园池占佳胜，高第干云霄。","不惜千金重，雅意一日遨。","绮筵镇水陆，清歌间笙匏。","酒酣视天地，泰山一鸿毛。","中情既昏惑，外体亦劳焦。","谁似林居子，神理恒超超。"]},{"t":"拟古四十一首 其十九","f":"五言古诗","c":["在阴鹤相应，迁乔鸟当歌。","琴书满瑶席，良朋亦已多。","各爱芳菲时，共惜光阴过。","齐心何所求，所求保太和。","壮年不努力，奈此老大何。"]},{"t":"拟古四十一首 其二十一","f":"五言古诗","c":["庭前双榴树，叶密枝相交。","时当四五月，吐花红夭夭。","人爱花烂漫，我爱花始苞。","尧夫有妙识，造化满即消。","情知酩酊醉，还见离披凋。","所以大圣人，持盈不忘劳。","吾今老学易，看花遂成谣。"]},{"t":"拟古四十一首 其二十二","f":"五言古诗","c":["虞帝尚钦恤，大禹泣罪人。","所以圣者心，天地同一仁。","周政失其御，侯章僣无伦。","刍灵既莫施，作俑亦不闻。","秦穆一朝逝，殉以三良身。","临穴殊懔慄，仰天亦悲辛。","古犹惜累辜，如何杀俊民。","王诛一以失，流毒荡无垠。","骊山锢重泉，银海通幽津。","遂使三秦众，半作地下尘。","天道本好还，嬴族亦沉沦。","因歌黄鸟诗，重为仁者陈。"]},{"t":"拟古四十一首 其二十三","f":"五言古诗","c":["回观自古来，黄金世所急。","郿坞几万斤，梁苑亿千镒。","贪求刻人骨，堆积盈家室。","宁知造化权，随时有消息。","人无长盛年，物无不散日。","金穴竟荒虚，金谷亦空寂。","发冢尚有儒，胠箧岂无力。","长见聚金人，终为大盗积。","往者既悠悠，来者方役役。","旨哉庄生言，独无郢中质。"]},{"t":"拟古四十一首 其二十四","f":"五言古诗","c":["蒿莱不招凤，梧桐不栖鸡。","物故各有趣，高卑焉可齐。","伯夷居东海，吕望钓磻溪。","峨峨太行巅，荟蔚方朝跻。","阳光烛四表，发轫岐山西。","二老既云往，妇子争扶㩦。","固知贤圣人，去就关崇卑。","试听紫芝歌，坐见嬴道隳。"]},{"t":"拟古四十一首 其二十五","f":"五言古诗","c":["王良称善御，时方尚诡遇。","季子洛阳归，张仪关中去。","佩印誇乡里，驱车塞道路。","说合从与横，而取贵将富。","孟轲陈王道，反为迂阔误。","已哉无复言，远矣哲王寤。"]},{"t":"拟古四十一首 其二十六","f":"五言古诗","c":["骊珠不易探，至理不易论。","端木称达者，性道犹弗闻。","五十知天命，玄圣有遗言。","区区事末学，役役劳其身。","葩藻灭素质，声利迷心源。","有若亡羊客，秪见岐路分。","何当息冥升，来复求其根。"]},{"t":"拟古四十一首 其二十七","f":"五言古诗","c":["孤桐生龙门，檿丝出东国。","相合为素琴，不离君子侧。","清弹何悠扬，遗音为发越。","中涵千古心，养彼至人德。","云胡变新声，丝竹异古昔。","繁响难具论，哇淫日沦惑。","举俗逐时好，谁能称在昔。","万事亦复然，不独琴与瑟。"]},{"t":"拟古四十一首 其二十八","f":"五言古诗","c":["吾思一气大，浑浑无边方。","天机自流转，随至互低昂。","寒暑既代序，日月亦运行。","庶物勃然出，满虚各有常。","万化定厥基，终古为维纲。","大哉庖羲圣，有画粲以章。","易道谅斯在，请看阴与阳。"]},{"t":"拟古四十一首 其二十九","f":"五言古诗","c":["吾思洓水翁，志节一何高。","褰裳辞宥密，视若秋鸿毛。","古人不可作，流俗正滔滔。","色过夏畦病，意甚乞墦劳。","趋走信机巧，苟得还骄豪。","閒咏青蝇诗，载玩硕鼠爻。"]},{"t":"拟古四十一首 其三十","f":"五言古诗","c":["吾思鲁公仪，拔葵去织妇。","傅翼两其足，实惟天道故。","云胡世君子，大得兼小务。","生殖广田园，贩鬻罔泉布。","牙筹既自执，龙断复登顾。","彼哉何足言，义利各有悟。"]},{"t":"拟古四十一首 其三十一","f":"五言古诗","c":["蜩鸠笑大鹏，夏虫疑寒冰。","语之斯道大，心识何蒙冥。","属文箧笥满，读书栋宇盈。","徒劳一生力，了无寸见明。","谁言点也狂，鼓瑟有深情。"]},{"t":"拟古四十一首 其三十二","f":"五言古诗","c":["月盈乃生魄，阴极阳复来。","损馀补不足，天道良昭哉。","淳朴日浇散，斯理亦何乖。","既剥犹未已，丰亨尚增培。","君子过佚乐，小人穷之灾。","所愿均厥施，九域登春台。"]},{"t":"拟古四十一首 其三十三","f":"五言古诗","c":["万钟固知富，于性无加增。","千驷虽云众，难为身重轻。","达人抱大观，不以外物婴。","夷齐首阳饿，伊挚莘野耕。","清风激千古，贤圣留其名。","邈哉务光让，鄙矣蜗角争。","蝇营徒为尔，鸿飞自冥冥。"]},{"t":"拟古四十一首 其三十四","f":"五言律诗","c":["青山何岧岧，白云自超超。","云山日在望，开门两相高。","既喜山静止，还爱云飘飘。","秀色可揽结，吾其陟山椒。"]},{"t":"拟古四十一首 其三十五","f":"五言古诗","c":["大气浩无涯，厚地大气举。","形气自依附，人物乃中处。","刚柔生变化，阴阳行寒暑。","自古谓之然，满虚宁可数。","吾思弄丸翁，深情契斯语。"]},{"t":"拟古四十一首 其三十六","f":"五言古诗","c":["丹毂既云饰，翠盖亦时张。","驷马复在驭，鸾和自鸣锵。","执绥者谁子，升车气扬扬。","回旋逐水曲，驰骋登周行。","行人为之辟，谁不羡辉光。","胡取覆餗诮，而置郜鼎章。","轮舆虽云美，致寇安可量。","所以大易辞，负乘著厥祥。"]},{"t":"拟古四十一首 其三十七","f":"五言古诗","c":["洪荒日已远，文籍日以繁。","华伪灭真实，汗漫迷本源。","左氏已浮誇，战国皆诈言。","班马扬其波，蔚宗助其澜。","继者如猬毛，美恶爱憎间。","谅非董狐笔，尽信诚为难。","谁哉法宣圣，大典垂不刊。"]},{"t":"拟古四十一首 其三十八","f":"五言古诗","c":["人生苦不足，得陇更望蜀。","祖龙泛海行，刘郎祀灶术。","仙事俱茫茫，百年竟飘忽。","汲汲复营营，何时满所欲。","吾慕首阳翁，清风在山谷。"]},{"t":"拟古四十一首 其四十","f":"五言古诗","c":["庭竹生凉飙，明月从东上。","候虫草根鸣，夜静声愈响。","逍遥步阶除，悠然起遐想。","三皇五帝时，淳朴竟焉往。","王风降黍离，礼乐委榛莽。","反复千载间，霸业杂相长。","是非垂不泯，胜负在俯仰。","令人意难平，拨置聊自广。"]},{"t":"拟古四十一首 其四十一","f":"五言古诗","c":["人巧千万端，莫逃造化巧。","三王行仁义，子孙永相保。","绵历百千载，顺理得终考。","嬴隋南北朝，窃国骋暴狡。","社稷旋荒墟，苗裔悉剪剿。","天巧必胜人，人巧何足道。"]},{"t":"出金陵","f":"五言古诗","c":["金陵宿雨霁，杲杲秋日明。","缪承北阙召，促装出西城。","追随冠盖集，酌别临江亭。","徘徊不能别，去住难为情。","挂席晓风发，解缆早潮生。","抗手谢送者，令人意难平。","所愿各努力，令德崇端贞。"]},{"t":"江行三首 其一","f":"五言古诗","c":["石城上朝旭，宿雾渐已收。","大江何茫茫，柔橹泛中流。","钟阜犹在望，白云散岩幽。","两载宁无情，湖山忆同游。","佳胜邈难即，回想空悠悠。"]},{"t":"江行三首 其二","f":"五言律诗","c":["顺流驾长风，挂席何快哉。","青山若相送，两岸犹崔嵬。","恩召信光渥，报称知非才。","贞白有君子，宁不动中怀。"]},{"t":"江行三首 其三","f":"五言古诗","c":["我舟既云迈，长风起层波。","天水共渺茫，云岫纷嵯峨。","石城犹在望，赤岸还经过。","远堤秋树小，水国蒹葭多。","老遂金陵游，奈此佳丽何。","北归已陈迹，江行遂成歌。"]},{"t":"过仪真","f":"五言古诗","c":["匆匆过仪真，来往已三度。","兹行复祗召，严程还北去。","湖田收晚禾，长堤落秋树。","已远金陵山，渐近广陵路。","乘月宜舟行，牵者且莫住。"]},{"t":"夜泊广陵","f":"五言律诗","c":["夜到广陵城，已是三更后。","官船少停泊，驿吏劳奔走。","风清月色明，河汉粲星斗。","行思方摇摇，怀古复何有。"]},{"t":"高邮","f":"五言古诗","c":["又见高邮城，连延傍湖水。","水上红驿楼，登眺忆往岁。","昔逢春雪飞，今值秋风起。","岁华与人事，回换理如此。","中贞谅自保，期不愧行止。"]},{"t":"高邮湖","f":"五言律诗","c":["去年冒春雪，扬帆过高邮。","今岁属秋暮，长风送我舟。","湖心射日气，骇浪蹴天浮。","观象卦有涣，悟易情悠悠。"]},{"t":"淮阳怀古","f":"五言古诗","c":["淮阳古名郡，卧治有昔贤。","禁闼不可留，遗想增慨然。","顾我岂其俦，宠擢何连连。","本乏实德称，重为虚名牵。","抚心益自愧，怀人遂成篇。"]},{"t":"雨中渡淮","f":"五言古诗","c":["风雨渡长淮，波浪何冥茫。","两仪混不分，恍若窥洪荒。","舟人贪利涉，片席就空翔。","翩翩入烟雾，随风任低昂。","北岸泊水驿，暮雨益淋浪。","且喜对官烛，粲烂竟夕光。"]},{"t":"清河晚晴","f":"五言律诗","c":["向夕起长风，秋云静天宇。","清波流月光，白露下寒渚。","榜人喜晴霁，理楫夜相语。","早发过钟吾，漫漫见徐土。"]},{"t":"夜上吕梁洪","f":"五言古诗","c":["水村夜寥寥，秋月流空白。","牵舟上吕梁，逆浪涌寒雪。","愧彼役夫劳，当此滩水涩。","忆我四方游，江湖饱涉越。","祗召复兹行，恩重知才劣。","矢心复何如，长洪石如铁。"]},{"t":"过徐州","f":"五言古诗","c":["去年春正月，南泛彭城舟。","今岁值秋暮，北上溯长流。","踪迹信往复，景物惬观游。","风寒堤柳落，波减岸石稠。","白见高城堞，苍出远山丘。","何处戏马台，彷佛燕子楼。","化迁无停轨，事往不可求。","陈迹竟泯泯，虚名但悠悠。","览今亦怀昔，发声遂成讴。"]},{"t":"送欧阳宪副","f":"五言古诗","c":["凛凛谷中风，亭亭山上松。","风声亦何劲，松自无改容。","竞秀固妍好，弱植徒丰茸。","独于霜雪馀，卓然见高踪。","悠悠四十年，所遇多尚同。","欧阳信佳士，亮节抱始终。","苍苍岁寒质，展可为国庸。","适来述所职，归思何匆匆。","载歌君子篇，德期皓首崇。"]},{"t":"杂诗三首 其一","f":"五言古诗","c":["洪荒一何遥，悠悠几万载。","古迹竟茫然，古道复安在。","巍巍唐帝尊，放勋薄四海。","文明启中天，伦典粲而蔼。","鲁叟删述劳，于兹立圣轨。","寥落但陈编，抚事增叹慨。"]},{"t":"杂诗三首 其二","f":"五言古诗","c":["孰云天地大，形势两暌绝。","一气周流之，神理有昭格。","雍雍虞庭臣，穆穆贤圣德。","太和良在兹，畴咨方未歇。","所以祥凤仪，不独大乐阕。","如何此道非，千古空遗迹。"]},{"t":"杂诗三首 其三","f":"五言古诗","c":["山龙匪舜乐，卑菲真禹心。","大哉虞夏圣，忧民同一深。","既服四载劳，还弹五弦琴。","九功亦时叙，敕天尚遗音。","如何精一传，载往不可寻。","独有简册光，留照犹至今。"]},{"t":"西溪鱼跃为乐安杨贡侍御题","f":"五言古诗","c":["西溪渺何许，乃在杨林阿。","杨林古名族，乐安世其家。","家住溪水曲，林木相交加。","地僻网罟绝，溪邃游鱼多。","濈濈聚弱藻，洋洋戏新荷。","逆水微波生，仰沫细雨斜。","跳跃自有适，出没静不哗。","杨族有名士，考业咀英华。","爱此鱼性乐，契彼道味嘉。","乃知天机妙，万象皆森罗。","却鄙中散慢，宁效濠梁誇。","缅怀旱麓诗，载赋西溪歌。","永言继真躅，胜景垂无涯。"]},{"t":"龙江晓望","f":"古风","c":["两岸青山隐隐，一江白浪茫茫。","烟树高低城郭，风帆远近舟航。"]},{"t":"遣闷二首 其一","f":"七言绝句","c":["客中郁郁不自得，忽思古人读古书。","古书古人亦如此，吾怀不放将何如。"]},{"t":"遣闷二首 其二","f":"七言绝句","c":["少时都不解忧喜，壮年百虑搅我心。","我心默默向谁说，呼酒只对东风斟。"]},{"t":"临清曲","f":"七言绝句","c":["临清人家枕闸河，临清贾客何其多。","停舟落落无可语，呼酒只对长年歌。"]},{"t":"题墨牛二首 其一","f":"七言律诗","c":["青松落阴石苔上，雨馀百草芊绵长。","老叟牧牛牛性驯，牛背读书兴萧爽。","书中之味深且长，高睨盘古窥皇唐。","日暮驱牛下山去，风清月白天茫茫。"]},{"t":"题墨牛二首 其二","f":"七言律诗","c":["绿杨芳草被平坡，老人骑牛行且歌。","歌长扣角角欲碎，悠悠古意何其多。","布褐凉风生两肘，几度归来月明后。","夜深遗响入青云，应有知音与携手。"]},{"t":"蚕妇吟","f":"古风","c":["采叶者谁妇，蓬首面不洗。","年年丝作人家衣，短布裙穿不掩体。","绮罗不是养蚕人，三复斯言情不已。"]},{"t":"偶题","f":"七言绝句","c":["磊磊落落塞胸臆，推荡始觉心和平。","丈夫志量包宇宙，细故那得风波生。"]},{"t":"忆绣荣二孙","f":"七言绝句","c":["绣孙犹未识阿翁，翁在山东一马骢。","近别荣孙春又夏，相应学语问阿翁。"]},{"t":"赠刘佥宪","f":"古风","c":["古磬不谐人之耳，古瑟不合人之心。","茫茫天地亦大矣，人生岂谓无知音。","阳春白雪听者寡，巴人下里和如林。","退之奇崛篇，子美烂漫吟。","谪仙逸气隘六合，一字价抵千南金。","神游八极不可见，独留文字几千卷。","江河万古行地中，饮者杯勺各满愿。","我生其后欲追逐，蹇若跛鳖趋紫燕。","东西南北流览多，公取古词各矜衒。","迩来忽遇刘虚庵，胸中元气何潭潭。","沉酣百子索幽怪，模镕万象穷川岚。","兴来落笔亦何壮，一日千里驰风帆。","又若秋溟露毫末，明珠大贝相错参。","始悟古人今可学，嗟我见晚生腼惭。","虚庵虚庵真奇士，磊落声名固应尔。","相逢一曲伯牙琴，高山峨峨水清泚。"]},{"t":"茅屋漏","f":"七言古诗","c":["辛丑进士河汾客，早向中州买居宅。","宅有茅屋八九间，补葺聊以蔽床席。","进士所好惟诗书，衣食取足无剩馀。","朝朝暮暮诵周孔，行行坐坐歌唐虞。","以兹狂僻误生理，老屋支撑几星纪。","前月大风撮茅去，今月久雨漏不已。","移床徙榻那得乾，堆书捲被空长叹。","文章不足补穿漏，翻为儿女生腼颜。","豪家大屋足欢笑，已觉纨裤轻儒冠。","却忆唐朝老工部，西蜀草堂几风雨。","亦有官居鼎鼐尊，欲起楼台无处所。","昔贤穷达还复然，我何愠此沾湿苦。","且待天晴饱读书，比屋渠渠不须数。"]},{"t":"太行歌送丁分教之襄陵","f":"古风","c":["太行之山何崔嵬，铁崖翠壁万仞中天开其势北来。","吾不知其几万里，但见横亘辽碛包括秦晋斗起中原之地何壮哉。","往年吾尝陟其顶，四顾山如培塿树如苔。","黄河一线遥遥下，砥石奔流直到东海不复回。","此时英风浩然洒六合，便欲历览天上金银台。","其中羊肠九折走峻坂，摧轮怪石硱磳磊落而成堆。","太行之高且险也如此，子今远行令人兴难裁。","倘到昔所登览最高处，为我歌此一曲还徘徊。","西望襄陵迢迢秪几驿，驱车径须往渡清汾隈。","愿子居易思险慎厥守始终，保令誉慰我相思怀。"]},{"t":"永和双山歌","f":"七言古诗","c":["永和四境千万山，双山之势尤㠝岏。","两峰对峙若天阙，中有一境通人寰。","南峰突兀半空里，连岫峨峨方并起。","苍松古木何萧森，朔风搜搅鸣不已。","北峰形状尤奇瑰，怪石刻镂楼与台。","上有云屏立霄汉，隔碍星斗回风雷。","我来登览值冬暮，攀缘石磴到高处。","沧瀛碣石觉东倾，弱水昆崙在西顾。","俯瞰累累冈阜多，巨壑无底如盘涡。","远近幽深杳难测，寒云冷雾纷荡摩。","因思未辟天与地，澒洞无涯惟水气。","轻阳一隙渐飘浮，大块无边遂凝滞。","波涛荡漾成高低，刚为金石柔土泥。","此山想得阳之极，层峦削出天之西。","独恨古来壮游者，足迹不到兹山下。","遂令奇绝委幽穷，无由题品继风雅。","我才虽非作者流，爱此欲去还夷犹。","摩娑石壁写长句，千古当与山同留。"]},{"t":"凤凰台歌次虚庵韵","f":"古风","c":["吾闻凤鸟不与凡禽栖，隆周之时曾集丰镐西。","锵然一鸣向人世，喧啾百鸟不敢争与啼。","昔有名臣黄霸生汉世，治民之才迥与时流异。","颍川出守曾几何，休风数感灵禽至。","灵禽文彩明山川，和音哕哕闻中天。","遂筑高台表神异，台空凤去馀千年。","只今坏埒才数尺，野鸟纷纷竞来集。","简册空存纪瑞年，荆榛不复快睹迹。","我来跋马登高丘，荒台已远犹回头。","为忆循良心耿耿，缅怀瑞物情悠悠。","凤台凤台重披访，往事何须空怏怅。","方今圣明治理登俊良，会见一朝飞去青云上。"]},{"t":"舟中苦热","f":"七言古诗","c":["大江千里流炎日，暑气波光互蒸湿。","火云压风空不来，舟中苦热何太剧。","坐睡昏昏汗雨流，对食欲餐还复休。","扣舷直欲发狂叫，安得少昊回清秋。","安得少昊回清秋，一洗烦热情悠悠。"]},{"t":"洞庭湖歌","f":"七言古诗","c":["吾观庖牺龙马图，五行惟水居其初。","自从清浊奠高下，山泽通气无时无。","荆南之水亦众矣，壮观惟有巴陵湖。","世俗相传八百里，足迹未到空踌躇。","今秋持节来南楚，舟泊岳阳访奇古。","登楼始得肆遐观，万顷洪涛际天宇。","如从东岱窥沧瀛，一点仙山隔烟雨。","长风歘起层霄间，渤渤汹汹增狂澜。","轰天揭地急雷鼓，排空炫日堆银山。","须臾风止波涛定，涵泳虚空开玉镜。","金乌饮渊千丈红，白鸥落影一行动。","行客喜甚无氛埃，连翩大舸争往来。","我亦飘然下楼去，放舟中流何快哉。","蜀江西来半天泻，潇湘南接苍梧野。","一剑横空有所之，丈夫不作悠悠者。","洞庭洞庭七泽雄，邹鲁昔有观澜翁。","我今赋此良不苟，乃知有本无终穷。"]},{"t":"沅州春日歌","f":"七言古诗","c":["南州二月春来早，绿水青山四萦绕。","城中何处足春光，御史台中富花草。","窗外青梅结子稀，门墙桃李争晴辉。","映日红绡正缕缕，漫空白雪何霏霏。","芍药锦苞犹未启，兰荪露叶光泥泥。","杨柳风搓碧玉丝，芭蕉叶吐青鸾尾。","苔茵展地萱草长，千红万紫遥相当。","竹林好鸟自鸣寂，菜畦蛱蝶殊悠扬。","生意由来满天地，妆点池台足佳致。","门清祗觉白昼长，庭閒况复游丝细。","静观元化深无涯，中心默默含春熙。","愿效冰霜达阳气，普期八表仁风吹。"]},{"t":"杜鹃行","f":"古风","c":["昔读古人书，知有杜鹃名。","今泛沅江船，始闻杜鹃声。","杜鹃生子不自哺，野老相传之语如少陵。","惟有古来称望帝，变化无端竟茫昧。","吾意百鸟相推尊，亦如蜂蚁君臣义。","气化感物不自由，四月五月声喧啾。","一声未了声转急，千林万壑波涛秋。","远客扁舟睡难著，两耳还遭杜鹃聒。","归心一夜忆虞廷，鸣凤时应集阿阁。"]},{"t":"续杜鹃行","f":"古风","c":["杜鹃变化有无宁复论，百鸟之中乃为众鸟尊。","以兹少陵托忠愤，再拜谓是古帝魂。","我来何处闻逸响，扁舟夜泊沅江上。","林霏拂岸滩风清，峡影沈波江月朗。","下远乍近鸣未休，听之转急如有求。","远客毋劳厌恼聒，少陵忠义方难俦。"]},{"t":"壶头歌","f":"七言古诗","c":["沅水南来几千里，乱石激涛蹴空起。","急捎官舫上巉岩，閒倚驿楼看山水。","隔江万叠云峰稠，一峰平立名壶头。","云是伏波驻兵处，至今石室留山陬。","忆昔炎纲断如缕，草窃纷然㩀寰宇。","宁知田牧隐奇才，挥斥奸庸识真主。","西征实藉聚米忠，南伐谁比铜柱功。","中兴诸将数筹略，直与贾邓争豪雄。","老身甘向边陲殁，誓扫群蛮静坤轴。","壶头战死非无情，天遣英灵镇南服。","跳梁小丑胡为哉，竟因遗算稽颡来。","虽云未雪薏苡谤，白璧本自无纤埃。","昔于青史叹高识，今向荒山访遗迹。","怒涛犹带薄伐声，愁云似是忠愤积。","马侯马侯真丈夫，大器自与凡材殊。","庙食勋名几千古，英风激我章句徒。"]},{"t":"骢马行春歌为陈侍御赋","f":"七言古诗","c":["五百启运天地清，群贤奋翼风云生。","九重治理达远迩，王度实藉执法明。","同年才子青云客，意气昂昂超等列。","孤松耸壑见高标，一鹗横空叹奇绝。","今年持节辞金台，青骢蹀躞万里来。","乃知霜雪达阳气，马蹄到处山花开。","邂逅沅阳话畴昔，昔曾联步趋文石。","豸冠已觉凝秋霜，绣服还应绚朝日。","沅阳宪署情何多，连床对榻同吟哦。","吟哦未已欲将别，索我骢马行春歌。","愧我诗才劣韩杜，长篇险语急难就。","强操纸笔为君题，挂一何止于万漏。","骢马骢马登周行，揽辔直拟清四方。","发奸凛凛息豺虎，洗窟蔼若回春阳。","古来豪俊皆如此，陈言雅欲追芳趾。","相将努力笃忠勤，图取英声耀青史。"]},{"t":"歌风台歌","f":"七言古诗","c":["素灵夜哭秋郊月，汉祖吴钩三尺血。","芒砀云气从飞龙，咸阳竹帛随烟灭。","独屈群策驱群雄，汉中一旅红旗东。","韩郎对语识成败，董公遮说开天衷。","王者之师仁以武，诸侯效顺力如虎。","关河百战芟群雄，垓下一歌散强楚。","风尘荡涤天下清，万乘不忘布素情。","黄屋归来见乡邑，宴饮父老如平生。","酒酣拔剑高歌起，歌词激烈振天地。","雄志深知大业难，霸心尚思猛士倚。","群儿逐和声悠扬，起舞四顾何慨慷。","乐极哀来泪沾臆，魂魄千秋思故乡。","遂令此邑为汤沐，独承天宠何优沃。","四百休运同始终，三国遗民想兴复。","至今有台泗水滨，雄豪一去馀千春。","坏埒层层积苍藓，平原漠漠生黄尘。","我来正值清秋暮，桑柘萧萧叶飞雨。","泗水南流芒砀高，霸业王风复何许。","徘徊重是古帝郊，摩挲石刻心劳焦。","俯仰秋天莽空阔，杳杳鸿鹄凌风高。"]},{"t":"昆阳行","f":"古风","c":["策马从北来，南涉沙河渡。","登岸得平原，极目风景暮。","暮天落叶何纵横，翻翻乱触马足鸣。","苍山无数昔人远，前瞻忽及昆阳城。","城南滍水流城郭，英雄事业犹如昨。","白水真人在侧微，谨厚伊岂常情度。","是时炎运寒如灰，五威使者车奔雷。","惨惨三精云雾塞，萧萧九县飙风回。","真人一怒奋神武，手握赤符兴义旅。","昆阳大战开天功，乌合如林散何许。","吾想当日严杀多，洗兵雷雨何滂沱。","滍川倒流虎豹伏，乱麻尸积山嵯峨。","自尔威声震天地，凶魁恶党䰟飘逝。","夏后周宣果再兴，成功磊落光前世。","悠悠此事千馀年，至今父老犹相传。","我来正值太平日，战地尽作桑麻田。","生平游览好奇特，徘徊吊古中肠热。","举鞭一笑寒天高，万里关河坐超越。"]},{"t":"襄阳歌","f":"古风","c":["持节过樊城，南渡汉江曲。","汉江远自嶓冢来，遥望真如鸭头绿。","江干楼堞何峥嵘，壮哉快睹襄阳城。","少日常思一游览，今朝始遂来经行。","经行处处多遗迹，满目苍然悲思集。","后人游似前人游，古人忆是今人忆。","郁郁岘山翠，遥遥鹿门深。","残碑人堕羊祜泪，隐居谁识庞公心。","庞公一去已千古，尚有清风洒寰宇。","茂林鸟宿鱼潜渊，区区刘表焉能取。","城南习家池，池水清涟漪。","当日山翁酩酊醉，风流未许他人知。","更寻王粲宅，留井岘山麓。","铜瓶无复汲深寒，蔓草空馀覆幽绿。","悠悠往事难具陈，高名尚有隆中人。","师出二表鬼神泣，图成八阵风雨频。","乃知襄樊士风好，由来英达何草草。","汉水东流岘首高，秪因配此名不了。","方今明圣坐垂旒，百年礼乐登虞周。","仁恩已满天地大，王化久浃江汉流。","江汉游女心如结，士习诗书仰先烈。","乌台使者来作歌，期与国风传不歇。"]},{"t":"游沅州城南","f":"七言律诗","c":["回环绿水流城陴，出门一顾心欢怡。","连林竹树献苍翠，缘江梅柳争芳菲。","和风荡耳沸箫鼓，晴日照水流旌旗。","沅湘信美匪吾土，中州久客还思归。"]},{"t":"寄颉文林侍御","f":"七言古诗","c":["前年挂席趋北斗，九月泊舟都门口。","绣衣人是同乡人，骑马江边问行久。","龙江驿里同徘徊，呼酒饮我何壮哉。","兴酣往事真草草，愿倾东海添樽罍。","别后倏忽几寒暑，吴江木落洞庭雨。","黔巫东望山嵯峨，恨不高飞插翎羽。","丈夫本是重四方，眼底道路如寻常。","风帆早晚下吴会，仍寻旧约歌慨慷。"]},{"t":"寄朱侍御歌","f":"古风","c":["吾观古来磊落大丈夫，致身特达自与凡才殊。","若不功作霖雨润枯槁，便当手持玉斧清寰区。","二者都应不可得，大田可稼长川渔。","生平抱此心耿耿，烂读古书极驰骋。","中年滥骑乌府骢，几载蛮荒苦便静。","忽闻按部同官来，江山六月霜风回。","楼船弹压湖湘百怪息，宪节荡拂溪洞云烟开。","是时思得欢然一相遇，何意黄鹄东飞燕西去。","令人凝望佳节过，开尽冬梅老春树。","春树纤纤柔叶多，沅江江上浩烟波。","喜得瑶华好音信，兴来独立东风歌。","歌成写寄凭双鲤，心事非公复谁理。","会合悠悠自有时，还期高议金门里。"]},{"t":"黔阳江行歌","f":"七言古诗","c":["黔江转急势未已，两岸苍崖削天起。","官船双橹疾于飞，倏忽云林过百里。","生平胆气尤崛奇，三年蛮徼甘奔驰。","恶滩险浪不经意，白日自保公无私。","空囊敝箧一何有，满束古书置前后。","船窗豁达涵虚明，书中得意宁容口。","忽忆江山千古长，不知何日开鸿厖。","阴阳争胜鬼神急，造化不停真宰忙。","千奇百怪气参错，轻飘重坠奠清浊。","三光宣精四海明，五行顺序百卉作。","有物不名复不凋，泯默万化常超超。","眼底江山未为壮，大地比是犹毫毛。","感此人生浪自苦，万事悠悠随所与。","放歌一曲南风来，坐对青天两无语。"]},{"t":"鹤山小隐","f":"七言古诗","c":["大江之右多奇峰，天台远与罗浮通。","鹤山苍苍在何许，嘉名独擅东南雄。","中有隐士好事者，作图远寄乌台下。","乌台柱史隐士交，持卷索我挥狂毫。","开图指点山佳处，峭壁回峦簇烟树。","涧花流出山中春，松风扫遍溪头路。","数椽茅屋何萧然，白云檐宇常周旋。","读易已了嘉遁趣，作诗或赋招隐篇。","此境初从柱史说，令人掩卷想奇绝。","振衣千仞或可期，万里云霄坐超越。"]},{"t":"齐都歌","f":"七言古诗","c":["偶把渔竿来渭水，诸侯八百从如蚁。","洗兵一雨天下清，兴王事业应难比。","茅土之封东土侯，奄有青济都营丘。","千乘龙旗照沧海，百层雉堞临淄流。","淄流拂曙歌钟起，人物喧阗隘都市。","黄金白壁酬君公，文马雕轩觐天子。","前朝后市何辉光，歌台舞榭遥相望。","长剑危冠盛皋虎，珠廉绣幕围姬姜。","伯业相传仅千载，宁知时去繁华改。","盗贼公然窃宝弓，坐令青社无光彩。","是非得失俱悠哉，空馀废址连荒台。","往事凄凉不可问，淄流呜咽悲风来。"]},{"t":"古松怪石歌","f":"七言古诗","c":["山东宪署两绝奇，古松怪石相蔽亏。","耳畔或闻海涛作，眼中不见云根移。","皮皴鳞蹙涩寒雨，霜雕雪刻莓苔聚。","方惊白日起潜蛟，更讶幽阴踞虓虎。","因怜二物争豪雄，壮颜毅色孰与同。","阅世不今亦不古，回头几觉凡物空。","岱宗千尺云昆崙，一勺水安得良工。","为我写此松石图，坐携造化入袖里。"]},{"t":"怀忠堂为都指挥李进赋","f":"七言古诗","c":["将军树勋起云中，结发慷慨从飞龙。","几年拥节驱罴熊，扶桑日出西崆峒。","旄头射落天山空，青海不复烽火红。","仁义之将良可宗，丈夫不数卫霍功。","时清包裹刀与弓，八蛮入贡重译通。","朅来分阃何从容，敦崇诗礼轻豪丰。","所居之堂名怀忠，怀忠事业应无穷。","我虽儒冠心颇雄，寸管不让三尺锋。","等閒禆补造化功，拟今四海歌皇风，怀忠将无与君同。"]},{"t":"登州行","f":"七言古诗","c":["骢马晓辞莱子国，北上高冈俯辽碣。","辽碣万里天风寒，山溪二月凌澌结。","空濛极目春无边，春涛汹汹摇春烟。","还从绝岭下长坂，高城忽起沧溟前。","沧溟倒浸红楼影，通衢豁达尘埃静。","已应持节是明时，况复观风得佳境。","天开海阔霜台高，霜台远思何飘飘。","巨鳌戴山真浪语，大方见笑非虚谣。","乾坤俯仰高歌起，有物无名大莫比。","瀛海茫茫未足誇，真是人间一泓水。"]},{"t":"望海歌","f":"七言古诗","c":["我生足迹半天下，朅来持节临东夏。","万里沧溟入壮观，洞庭彭蠡足惊诧。","三韩之西日本东，元冥少昊回祝融。","归墟尾闾杳难测，清江碧汉来无穷。","碣石依稀望中小，天台不断连山绕。","烟波明灭散群鸥，云水空青浮众岛。","扶桑渐觉明朝暾，还从海底升金盆。","太阴灭尽清辉发，羲和稳驾波无痕。","有时飓母逞神武，冯夷击鼓百怪舞。","白浪峨峨摧雪山，黑雾茫茫涨天宇。","三山六鳌安在哉，祖龙已去刘郎来。","楼船不复返秦使，云帆更欲寻蓬莱。","雄豪千古俱沦没，唯有潮声尚如昨。","从谁海上论盈消，独倚苍山看寥廓。"]},{"t":"东平行台十五柏","f":"七言律诗","c":["行台台上十五柏，一一皆抱梁栋姿。","自应生长得元气，更当培植需良期。","孔明庙前今在否，才大空闻少陵语。","何如此木生中原，万牛不用可立取。"]},{"t":"送王秀才省兄归京师","f":"七言古诗","c":["海右传闻此亭古，亭中送客豪英聚。","清风入座华筵开，流霞满眼金杯举。","是时霜落天宇高，岱宗南望干云霄。","况复齐川走沧海，三山恍惚连六鳌。","山奇海壮环名邑，落落高怀感今昔。","琬琰难酬北海词，风雨宁如少陵笔。","想当促膝兹亭中，飘飘逸气凌长空。","至今草木生光彩，名将山水传无穷。","皇明文运超唐李，鸣凤高冈鸣不已。","王君之府玉堂仙，清秩仍兼举三礼。","难兄早擢贤良科，内台执法平不颇。","朅来海岱振风纪，王君柰此想思何。","鸿雁联翩暂相接，又是离亭动行色。","萧疏荷芰飐秋波，凌乱桑榆下霜叶。","王君王君我所奇，不须怀古伤分离。","但愿埙篪迭相应，一门清誉流无期。"]},{"t":"琅琊行","f":"古风","c":["秦祖琅琊台，坡老超然台。","两台千古两寂寞，但见参差云木山崔嵬。","我行正值四海升平日，千里连城万家邑。","烽堠花开火不惊，林园麦秀雉争集。","茫茫一气天无私，山川民物皆欣熙。","三事小臣效精白，九重圣主方无为。","但愿此景垂过亿万载，天为城郭地为海。","人间无处不春台，苏刻秦碑真戏乃。"]},{"t":"山水图为赵给事赋","f":"七言古诗","c":["黄门给事好事者，一幅江山谁为写。","云雾波涛满眼生，坐觉襟怀自潇洒。","衡庐倚叠岷峨高，洞庭彭蠡洲渚交。","又疑雪消蜀水来，黄牛白马增春涛。","细看清浊分天地，地脉山形宛相际。","良工妙夺造化工，白浪青林走云气。","缘江细路古木齐，耳畔似闻幽鸟啼。","倚岸扁舟久将济，入云茅屋谁同栖。","江草山花不知数，采芳未是良辰暮。","英灵不闻涧谷歌，仁智自谙水山趣。","忆我昔游天下时，跋涉险阻探清奇。","何如此图不出户，胜槩一览无所遗。"]},{"t":"送赵大参之浙江","f":"七言古诗","c":["浙右新参拜天宠，赵君籍籍声名重。","晓辞仙仗出都门，骅骝塞道香尘拥。","交游送别情何多，离筵正值东风和。","山光入坐水侵席，柳条弄色花满柯。","花前罢酒官桥远，潞水开帆驿程转。","九重金阙尚驰情，千里吴山行在眼。","吴山自昔称繁华，居民比屋过万家。","西湖烟净拭明镜，海门潮起翻银沙。","复有孤山号清境，清溪浅露疏梅影。","处士不作封禅书，节与孤山共高耸。","大藩形胜甲南东，好山不尽湖江重。","薇垣轩豁挹清气，使符出入宣皇风。","皇风正是全胜日，圣明侧席求贤急。","方期礼乐过百王，直使仁恩涵八极。","赵君好体轩尧心，嘉禾莫使蟊蠹侵。","旬宣他日有成绩，策勋还作商家霖。"]},{"t":"送卢知县致仕归金华","f":"七言古诗","c":["高秋九月都门道，冠盖光辉耀晴昊。","离筵觞酌送者谁，花县郎官乞身早。","郎官自是青云姿，飞腾况值明盛时。","著书东阁见才俊，之官南国怜英奇。","英奇未了哦松兴，鹗荐升官播佳政。","单父横琴今几年，故里悬车想三径。","三径乃在金华阿，金华山水名且多。","绕户清溪漱寒玉，当窗秀岭横烟萝。","到家尽得溪山趣，交友过从乐相语。","为言壮仕老归来，此是天恩最深处。"]},{"t":"题罗侍御仙舟出峡图","f":"七言古诗","c":["御史新图妙难比，画船秋泛瞿塘水。","瞿塘水束三峡深，两岸削铁虚无里。","虚无难辨峰顶高，白云林壑生虚涛。","阳台何处笑荒幻，阵图回首思雄豪。","雄豪一去几千载，壮志何须增感慨。","自知豸角邪可触，不为猿声泪空洒。","东行更饱湖海观，绣衣不日朝金銮。","览君此画动清兴，扁舟便欲相追攀。"]},{"t":"题罗御史骢马行春图","f":"七言古诗","c":["青骢蹀躞长风起，蜀道南来八千里。","揽辔不觉群山高，釰阁峨眉平若水。","行边正值韶光浓，千岩万壑花争红。","晴霄丽日照旌节，芳郊草软摇玲珑。","三川玉斧巡将遍，父老欢传喜相见。","瘴厉都从淑气消，阴寒总逐阳春变。","阳春本自天上来，行春此日何壮哉。","还从画图识神骏，回鞭却上黄金台。"]},{"t":"张忠定公祠","f":"七言古诗","c":["乖崖自是奇人物，两回走马定西蜀。","才惊锦水云飞扬，坐见雪山峰突兀。","龙剑破匣摇寒芒，斩艾荆芥驱天狼。","父老但知歌舞乐，黎庶不觉科徵忙。","铁心一念真能止，侍女三年犹处子。","乃知金石诚可通，遂使西人信如此。","功成拂袖归几年，年深惠化犹相传。","蛟龙上天风雨急，声名垂世日月悬。","至今西人感公德，牲醑年年进公室。","回头却笑鄙猥徒，身名泯泯无遗迹。"]},{"t":"寄题广汉张魏公读书岩","f":"七言古诗","c":["广汉之山甲西蜀，闻有石岩在山麓。","想当英杰未遇时，携书独向岩间读。","岩间日月閒且长，远从虞夏窥黄唐。","幽探造化鬼神变，明察典礼人道常。","古书遍读饱经济，一朝适与风云际。","社稷频将赤手扶，砥柱不逐洪波逝。","金轮腾踔乾与坤，冥冥九宇皆兵氛。","要除和议正人极，誓迎北辙归中原。","其如䜛口增萋斐，一斥南荒垂二纪。","容光虽荷天开明，孤忠竟与时已矣。","俯仰于今几万秋，名将江汉无停流。","思公招公公不起，遥想寒岩添我愁。"]},{"t":"西蜀歌","f":"古风","c":["天险不可升，地险犹可登。","西蜀之山盘亘大地几万里，层峦叠嶂危峰峭壁何崚嶒。","西岭峨峨太古雪，巫山苍苍晓云白。","北有剑阁中天削出石门高，南有峨眉凌空夤缘鸟道窄。","群山合沓险远不可穷，危梯侧径无不相连通。","楩楠松柏古木不知数，攒峦架壑阴森蓊郁起烟雾。","野花涧草乱杂难具名，纷葩蒙茸齐沾天雨露。","熊罴虎豹猿狖相与为群曹，幽禽怪鸟雄飞雌绕各以时鸣号。","蜀山草木鸟兽之环奇也如此，登高一望但见千里百里峰峦涌翠如海涛。","中有长江横界井络域，发源岷麓东注沧溟无底谷。","深山幽壑溪涧千万支，穿林络石竟与岷江共联属。","蜀水行地山入云，东连吴会西昆崙。","梁州旧是禹迹九州地，谁言自古隔绝不与通中原。","忆我总角年，曾来到西川。","惟时记一不识百，白头回想空茫然。","前年丹诏下田里，布衣走马见天子。","擢官便作大理丞，持节重到三川里。","三川山水得纵观，笑睨重险轻狂澜。","不为三峡猿鸣堕清泪，不为五夜鹃啼惨旅颜。","老读古书破万卷，物理深深颇窥见。","大莫大于天无际，眼中山水足惊羡。","慨此悠悠险隘区，一分一合千古馀。","奸雄割据奴辈尔，干戈盗弄鼠子如。","独想南阳老诸葛，三顾茅庐鱼水合。","复汉功留二表中，出师星向五丈落。","至今庙食锦水头，讨贼忠义垂千秋。","下视纷纷草窃盗名字，泯没何异狐鼠澌腐埋山丘。","只今天开明运四海为家日，岷江安流道途夷坦险阻失。","我作歌词纪载混一全盛时，期与江山永永传无极。"]},{"t":"题刘都宪山水图","f":"七言古诗","c":["谁写新图妙难比，叠嶂连峰向天起。","逼人已觉爽气清，入眼浑疑暮光紫。","缘山细路分高低，云林远近何参差。","晴崖杲杲风日白，阴壑惨惨雷雨迷。","沙水微茫绕山脚，半空飞瀑银河落。","山光水色交清辉，世外尘氛尽消豁。","忆我壮游大地中，名山历览千万重。","良工巧夺真宰意，云气恍与诸山通。","刘侯家在江南住，正在此图好山处。","开门只见金芙蓉，散倚青霄不知数。","侯今官已都宪台，家山尚自萦高怀。","匡时未许赋归去，观图且喜清风来。"]},{"t":"题郑侍郎莲鹭图","f":"七言古诗","c":["高堂忽见华山顶，十丈仙花开玉井。","新梢出水藕横船，圆叶当空盖欹影。","纷披花叶相交加，绿云片片连红霞。","疑是瑶池宴仙子，酒酣肌理无纤瑕。","何处纷然下群鹭，伫立相呼复相顾。","六足联拳方比翼，一喙低迟还独步。","衔鱼仰视空外来，故知两意无嫌猜。","参差九鹭态度别，红莲香里同徘徊。","徘徊毛羽胜霜雪，散布苍烟几点白。","浑如野鹤出尘垓，回视凡禽迥殊绝。","匪独九鹭粲有光，就中饮啄性亦常。","不比饥鸢得腐鼠，仰首却嚇孤凤凰。","无限雕鹯与鹰隼，爪觜铦利性贪忍。","何如此鹭纯且真，不搏不击意深稳。","谁哉巧夺造化工，花鸟幻出丹青中。","㓗白真堪比君子，还歌振鹭鸣西雍。"]},{"t":"题角鹰图","f":"七言古诗","c":["疑是楚公戴角鹰，写出神气何棱棱。","健如熊虎一心猛，快若风火六翮轻。","旷野秋高草萧瑟，百万雄师大狝猎。","合围已见三面齐，翻韝似觉千里窄。","纵横搏击鸟兽群，风毛雨血何纷纷。","云里鹍鹏尚须避，草中狐兔宁复论。","罢猎归来立高树，似听风飙欲飞去。","安得真骨殄鸱枭，长见鸾凤在云路。"]},{"t":"画梅歌为朱大理题","f":"古风","c":["天地有清气，钟人亦钟物。","阿谁写出江南春，彷佛湖山见佳木。","老干何槎牙，柔条亦森罗。","疏枝夭矫相交加，花神幻出连空葩。","长风吹落天家雪，万蕊千枝晓争白。","瑶台仙子舞衣飘，姑射神人佩珠结。","冰玉之姿孰与伦，生来不受半点尘。","野草閒花真?屑，粗桃俗李徒纷纭。","物意有如此，人间真太奇。","庾岭何须访消息，孤山不用寻横枝。","但愿江山处处结真味，共与盐鹾调六气。","星骑箕尾若可追，编书垂誉过千世。"]},{"t":"山水图歌为蒲守徐孚题","f":"七言古诗","c":["谁写云山与烟水，爽气清风盈幅起。","想当解衣盘礴时，坐驱造化入笔底。","须臾削出金芙蓉，奔湍骇浪争朝宗。","元气直穿古石裂，悬流疑与银河通。","青林远近不知数，林内山房启晴户。","时清似有招隐歌，地偏不见采芝处。","我昔持节天下游，东穷海岱西梁州。","忽见斯图忆所历，江山清思何悠悠。","河东之守好奇者，特送图来索题写。","自知老大笔力微，挂一漏万语非假。","强裁长句卷还时，坐中尚觉留清飔。","仁知高怀在山水，贤守玩此应得之。"]},{"t":"送郑侍郎归省","f":"古风","c":["吾闻侍郎之父御史祖，阅世如今八十五。","飘萧鹤发未龙钟，巉岩俊骨自奇古。","侍郎蚤岁簪笔趋螭头，五朝出入迁擢宠渥稠。","往年龙敕推恩出天府，前年鸾诰封秩来庐州。","老亲荣贵重重真罕比，银章金带照耀乡闾里。","侍郎官署居南京，思亲只隔长江水。","今春乃上陈情归省章，报可丹诰飞下五云乡。","试问此时拜恩感恩意，东流之水与之谁短长。","便理南归旧囊橐，沙头潮退画舫阁。","京华相送尽公卿，冠盖追随出郊郭。","是时正值春光明媚春气和，柳条弄色流莺歌。","江草萋迷含烟竞驻紫骝马，江花凌乱随风飞拂金叵罗。","酒尽潮来挂征席，想到家乡秪几日。","升堂拜舞多弟昆，堂前罗列儿与孙。","歌曲庭闱沸丝竹，宾朋门巷如云屯。","大启华筵斟寿酒，欢声喜气倾前后。","齐言灵椿不老南山高，共愿亲龄与之同悠久。"]},{"t":"送安城戴勿谅归江西","f":"古风","c":["戴生大司成之侄婿，经授春秋究凡例。","春王正月大统明，西狩获麟笔削既。","二百四十二年指掌中，属辞比事须融通。","谨严独得昌黎老，大义特造伊川翁。","经世之书真大典，鱼鲁何如尚讹舛。","胸中要自有权衡，笔下何须苦裁剪。","戴生业此凡几年，一朝归兴何翩然。","连环屡梦老亲面，兰桡便理西江船。","江头载酒纷纷来送别，半是青云之器桥门客。","离情草草何足云，英论滔滔殊未竭。","明维九月天宇凉，洞庭木落南雁翔。","丹枫耀日染霜叶，白云映水摇秋光。","祖筵酒尽挂征席，千里乡闱秪几日。","升堂拜舞称寿觞，倍觉双亲喜盈溢。","双亲之喜将何如，有子一别三年馀。","但得经书载子腹，绝胜甘旨左右趋。","戴生起拜奉亲志，读书须学圣贤事。","古来声利等浮云，直自麟经溯洙泗。"]},{"t":"春江送别为陈侍御兄赋","f":"七言古诗","c":["有客有客官内台，难兄千里拿舟来。","典衣沽酒共欢笑，狂歌放饮怀抱开。","灯前几时同聚首，又复匆匆各分手。","借问归期何太忙，荅云慈母相思久。","交游出祖春江边，春江杨柳含青烟。","维舟荡漾碧波里，倾觞潋滟飞花前。","玉瓶酒尽征帆发，咫尺风涛分楚越。","沙上鹡鸰相背飞，云间鸿雁分行别。","莫云去住难为言，谁似君家贤弟昆。","难弟致身位方达，难兄归养名何尊。","想到淮南春未老，慈亲手弄连环好。","称觞正值佳节和，戏綵偏宜晴日皎。","切切丁丁母子情，为言官况清如冰。","会有鸾章下霄汉，褒封永作家门荣。"]},{"t":"送虞宪使考满之京","f":"七言古诗","c":["山东宪使何昂藏，铁心古貌眉发苍。","出入四朝荷天宠，操持一节飞秋霜。","海岱茫茫几千里，十年监部平如水。","只今报政趋神京，僚庶追攀情不已。","薰风杨柳城西亭，绮筵别酒倾银瓶。","一举十觞劝公饮，气酣感我千古情。","千古之情向公道，要使苍生乐熙皞。","内台黄阁正需贤，此去严程到须早。"]},{"t":"醉吟楼歌为刘佥宪父赋","f":"古风","c":["醉吟之楼高且雄，谁其作之醉吟翁。","翁心豁落真宰同，作楼直欲凌苍空。","危梯缥缈叠撑拄，层轩洞达相开通。","白云片片宿梁栋，青山隐隐当帘栊。","长夏绝超爽，灵风洒清响。","秋蟾散影九万里，晓雪悬光一千丈。","四时风景佳，翁来日登赏。","赏心苦未足，呼酒涤尘想。","一觞一咏自风流，兴酣万物良悠悠。","傲睨五岳众山小，吞吐七泽三江秋。","有时醉倚阑干望八极，便欲排风御气仍丹丘。","却思李杜文章伯，只今已作神游客。","举杯且复一招之，招之共饮楼头月。","月光入口清心魂，唾珠洒作澄江雪。","澄江雪，何茫茫，瑶翻玉涌蛟龙翔。","是时翁与二子相颉颃，搜括百怪神鬼藏。","陶镕万象造化忙。","乃知醉吟楼，不让采石江边亭，浣花溪上庄。"]},{"t":"遇知行简陈广文","f":"古风","c":["岂不闻北海鹏。","扶摇一夕起，抟击九万程。","又不见渥洼驹。","朝饮东海水，暮宿昆崙墟。","古来磊落奇男子，变化腾骧亦如此。","英风激烈干云霄，伟绩轩轰冠青史。","我昔年少天下游，大河南北西梁州。","望远将登岱岳顶，观澜欲泛溟渤流。","尔来战艺梁园日，秋月离离桂花实。","更随春水到龙门，一跃风涛生霹雳。","中间敛翼就閒居，峨冠且复歌唐虞。","半载悠悠客京索千钱，僦得城南庐。","城南之庐绝萧洒，开门直见南山下。","南山朝青暮亦青，人情谁似山光者。","陈夫子，儒之豪，早年独步亨衡高。","雄文应不让班马，清词真可追风骚。","籍籍才名三十载，到处菁莪秀而蔼。","春生杖屦乐薰陶，霜吼金钟共倾骇。","众人视我同众人，先生视我情何真。","乃悟知音古来少，伯牙独与钟期亲。","先生剩注樽中绿，我为先生歌一曲。","老天生才既有需，岂向尘埃长碌碌。","一歌既竟还复歌，歌长此意将如何。","残冬便须终日酩酊醉，春来喜见万里风云多。"]},{"t":"题王司训汶阳亲舍图","f":"七言古诗","c":["先生累叶居邹鲁，礼乐诗书绍先祖。","夫子遗风饱已闻，杏坛遗迹频经睹。","一自宾兴上玉京，便拜除书绾丝组。","官在中州千里馀，回首乡关路修阻。","为因甘旨缺晨昏，故遣良工写乡土。","淡霭初分岭上村，轻烟乍点天边树。","洙泗微茫洄不流，龟蒙岌嶪黯将雨。","凭轩忽若无丹青，汶水之阳见庭宇。","花间一鸟窥帘栊，竹里儿童随杖履。","静听如闻琴瑟鸣，细看似觉斑斓舞。","先生乃是纯孝人，思亲对此融心神。","锦衣有日遂荣养，寿觞更祝如大椿。","吾闻昔日唐忠臣，大行跋马高嶙峋。","白云孤飞绕亲舍，望之不觉涕零巾。","至今香名满人耳，先生岂不追芳尘。","愿将此图莫轻掷，子孙永作传家珍。"]},{"t":"留别王大尹","f":"七言古诗","c":["忆昔年少登公堂，公堂开宴罗笙簧。","红烛传觞鹦鹉煖，锦笺落笔蛟龙翔。","贤侯爱客情无已，留连夜宿重帘里。","香消古鼎语未阑，月满雕梁眠未起。","中间契阔十年馀，千里关山恨索居。","何意今朝复相见，烹羊酾酒为欢娱。","愧我马蹄随计吏，朔风又捲河梁袂。","握手难忘父母邦，铭心佩感贤侯义。","贤侯之义孰与俦，冰壶玉鉴涵清秋。","报政行将觐明主，春花相约凤池头。"]},{"t":"题醉仙图","f":"古风","c":["画图忽见瑶池仙，排风驭气今几年。","弱水蓬壶恣往还，沧海见说成桑田。","流霞之酒如长川，偶来醉倒东风前。","长松落落芝芊绵，群仙倚侧坐与眠。","壶既为之倾，瓢亦为之颠。","沈冥不管山花妍。","拂袖凉飙神凛然，共骑黄鹤凌苍天。"]},{"t":"赠同年","f":"古风","c":["吾闻洞庭之水几千里，巨浸茫茫接南纪。","蛟龙夜舞风涛寒，鸥鸟晴浮镜光紫。","岳阳之楼高且雄，元冥北牖南祝融。","娲皇误落补天石，君山一点玻璃中。","咄此湖山两奇绝，孕秀储精此其穴。","应有贤俊生乎间，岂独崧高产英杰。","我昔年少天下游，只今三十来神州。","同时射策揔豪迈，翩如彩凤翔高丘。","有客昂藏好眉宇，家住巴陵几今古。","已应秀气钟湖山，更觉词华绍先祖。","偶骑鲸背游赤霄，赤霄仙子争相招。","想当沈醉碧桃下，一花吹落春江潮。","自尔楼神元圃侧，炼气餐霞学胎息。","一朝九转就还丹，羽化千人万人识。","清水芙蓉吐异葩，兰苕翡翠相交加。","珊瑚色明海底树，云锦光吐空中花。","紫府之名照丹箓，钧天细听箫韶曲。","欣逢明圣登俊良，喜遇升平调玉烛。","马蹄共踏金台春，与君义气殊相亲。","志节功名须努力，赓歌愿作虞廷臣。"]},{"t":"金台春意图为夏进士赋","f":"七言古诗","c":["西山千仞插天碧，东海排空浪头白。","山雄海壮拥神京，中有金台临紫陌。","台高迢递绝尘埃，九天星斗罗三台。","台前一夜东风起，吹得皇都花柳开。","花枝杲杲明朝旭，柳色依依袅轻绿。","九衢车马睹晴辉，万井笙歌连曙烛。","有客磊落丰城人，宝剑出匣光芒新。","两度青云不得意，今年一举超常伦。","金台骀荡春光好，对策彤庭漏声晓。","宝殿胪传瑞气多，天门榜放祥云绕。","锡宴南宫春昼迟，锦袍不管杯淋漓。","醉向和风满归路，紫骝蹀躞争骄嘶。","绮楼翠牖出云幕，粉黛朱颜拥芍药。","倾城人看绿衣郎，意气昂昂动寥廊。","幸逢明圣坐垂旒，联翩彩凤鸣高丘。","成名祗向雁塔写，放歌不作平康游。","金台春色看未已，又沐天恩还故里。","尽将此意入丹青，期与乾坤传不毁。"]},{"t":"送刘侍御","f":"古风","c":["青骢晓嘶春日明，银鞍稳被珂玉鸣。","豸冠绣服何光荣，乃是鸟台柱史朝神京。","故乡之山郁峥嵘，绿溪白石蒲芽生。","交朋相送难为情，大搥鼍鼓吹匏笙。","四筵列坐皆豪英，高谈直使鬼胆惊。","醉来不觉金罍倾，起舞意气殊纵横。","我歌一曲送君行，丈夫立志当轩轰。","古来多少彯华缨，惟有忠义留芳名。","岂无铁面寒，亦有揽辔清。","愿君追取二子烱烱之精诚，仰酬盛世开隆平。"]},{"t":"苦雨","f":"七言古诗","c":["凉风飒飒雨声急，出门跬步苦沾湿。","山城拂地云雾深，河渚交流潢潦溢。","田夫野妇坐叹息，园中有枣不可食。","况复离离禾黍垂，及时不得收穫力。","一年百事望秋成，秋成奈此淫雨积。","谁哉为我诛云师，宛见青天行白日。","男亦欣欣女亦欢，有衣有食安家室。"]},{"t":"郊游","f":"七言古诗","c":["客居烦聒毒我肠，偶骑款段登周行。","西行三里渡小水，北上百步临高冈。","远近人家翳乔木，依稀邮舍围垂杨。","是时陇麦半乾槁，南风起浪日色黄。","所遇林桑已空兀，谁家妇女犹提筐。","惟南有山接嵩少，云门开阖峰低昂。","清回爽气彻心目，便觉尘虑都消忘。","回鞭窈窕历溪谷，野花野草供幽香。","壳蜗垤蚁各生遂，潜鳞飞鸟咸徜徉。","东折萦纡历平坂，纵观大化穷毫芒。","乃悟群生隐无极，始知一气包鸿荒。","此意悠悠真罕识，令人酷忆点也狂。","缓辔归来日已夕，满怀风月天茫茫。"]},{"t":"故镇行","f":"七言古诗","c":["北山崒嵂界天碧，山前古境烟霞集。","两街老木风飕飕，几道寒泉声沥沥。","沟塍缭绕禾麦稠，椒林果实被道周。","人家门巷甚萧洒，村园水石殊清幽。","西边梵宇临深谷，俯视溪田蔼新绿。","钟阁风云入壮怀，佛殿金银炫尘目。","断碑苍藓还摩挲，细看岁月良已多。","赵宋金元迭兴构，黄童白叟争奔波。","誇雄竞丽犹未已，衰歇几何还又起。","大道由来甚坦夷，何不归斯而舍彼。","亲朋导我村北行，丛祠户牖涂丹青。","龙堂鬼物极雄怪，土祠洞府何幽冥。","还复崎岖历西涧，褰衣竞涉波凌乱。","高柳啾啾栖暮禽，平芜渺渺语飞燕。","嗟哉此境良亦稀，游览未毕情依依。","念我昔年走天下，每逢山水娱清辉。","况兹故里好林壑，有田可耕薪可斫。","待余他日重归来，拟卜山居寻旧约。"]},{"t":"西硙行","f":"七言古诗","c":["偶来与客游山前，地幽便觉人境偏。","路入青林几萦曲，浓阴不断风泠然。","㶁㶁清泉来远谷，绀色寒声瑩心目。","石梁急泻跳明珠，草岸平流浸青绿。","北行更欲寻泉源，山门蓄雾势吐吞。","两峰秀出半空里，锦屏屹立当中尊。","复憩山□小琳馆，洞户云扃殊宛转。","袖拂尘埃读古碑，茶馀苦乏青精饭。","归来白日天未中，回头尚爱千云峰。","更待秋初稍凉冷，还登绝顶窥鸿濛。"]},{"t":"峡石山行","f":"七言古诗","c":["古道黄泥没车毂，峻坂迢迢客行苦。","别寻细路出山椒，俯瞰群峰如累土。","山椒怪石何巉岩，小大累累儿逐母。","忽惊耳畔过狂飙，老木如人自掀舞。","阴阴空谷啼饥猿，惨惨深林啸猛虎。","时时一顾破羁颜，秋叶秋花解媚妩。","霜林色重红欲然，露菊香寒寂无语。","日暮崤陵风雨来，千山万谷堆云霾。","回视人寰不知处，恍疑驭气游蓬莱。"]},{"t":"新安行赠王广文","f":"七言古诗","c":["西通崤沔东洛阳，涧流曲折波浪浪。","连峰叠巘互低昂，溪桥野店遥相望。","函关开豁地一方，新安老树浮高隍。","山回川合郁苍苍，储精孕秀不可当。","钱君若水慎行藏，急流勇退何徜徉。","韩侯擒虎智力强，高勋亦可铭太常。","其馀豪杰皆昂藏，弱毫未易俱谈扬。","王乔古洞南山阳，世传铁斧殊荒唐。","洪炉烈焰徒煌煌，百炼不改纤毫钢。","古来雷斧坠穹皇，阴阳抟结成锋铓。","铁斧无乃类此行，胡为末俗相惊惶。","我行爱此山水乡，往来屡宿芹頖堂。","芹頖广文情慨慷，时能取乐行华觞。","诸生罗列芝兰香，争持斗酒浇我肠。","醉来意气何扬扬，为之放笔扫秕糠。","掇拾故迹百十忘，颇胜燕石为琳琅。","欲行不行意徊徨，明朝别思俱茫茫。"]},{"t":"寄温县江司训","f":"七言古诗","c":["君住江南我江北，关河千里万里隔。","一朝振翮起翱翔，同逐春风游紫陌。","是时英俊天下来，南宫角艺何壮哉。","岂意主司滥收采，缪将寸木升崇台。","君持木铎向温邑，曾问士风解愁寂。","我亦拜恩归读书，却抵荥阳问家室。","荥阳温邑隔大河，相寻一苇曾经过。","严亲今岁官河内，往来扰扰如奔波。","爱君特达好心事，一回相见一欢恣。","夏馆清谈移昼阴，秋斋共宿发幽思。","有时酌我金屈卮，我还荅以二鸟诗。","醉来意气觉奔放，生平肝胆何崛奇。","近日分携隔风雨，羁怀落落向谁语。","行将跨马过君家，寄声为酿新秋黍。"]},{"t":"送萧都宪归盘窝歌","f":"古风","c":["古扬州之域，今大江之西。","名山名水相望其间罕与之齐。","龙泉乃在山水最佳处，盘窝直与盘谷争胜足以成幽栖。","吾友萧君生其邑，钟秀精英抱高识。","神骏早掣飞电踪，大鹏快展扶摇翼。","天上迢迢十二楼，鸣佩早与群仙游。","东俯扶桑枝，西瞰昆崙丘。","珊瑚文彩沧瀛流，吴钩光射瀚海头。","声誉喧喧鬓未改，赐归倍觉天恩大。","萧萧行李出都城，漠漠云帆挂淮海。","长江西上知几程，家山次第来相迎。","盘窝林岭秀，盘窝水石清。","东潭西障迭隐见，马山龙洞相纡萦。","离口横波秋色冷，朝帽之峰露高顶。","平林归翼晚来稀，远浦渔舟歌韵迥。","云陂春牧散无边，高野秋禾成万井。","盘窝之景何其多，萧君柰此盘窝何。","或时采其山，或来钓其波。","松根茯苓自可斸而煮，松花崖蜜亦可调而和。","山间茅屋极萧洒，岚霭氤氲清水泻。","静时玩易窥见天地心，閒日弹琴并与亲朋话。","盘窝之乐难具陈，应知道卷堪怡神。","但恐勿乐有喜鹤书飞来自天上，东山谢老未许独乐忘生民。"]},{"t":"铜雀台","f":"七言绝句","c":["铜雀台高春日明，春风无限绮罗情。","笙歌莫向西陵奏，松柏萧萧起暮声。"]},{"t":"春日即事","f":"七言绝句","c":["一夜东风柳穗柔，晓来红日在帘钩。","少年两两鸣鞭过，唯见香尘扑马头。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其一","f":"七言绝句","c":["公等文章班马俦，偶来联步上瀛洲。","天恩又许归乡里，同泛南风五月舟。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其二","f":"七言绝句","c":["天上同沾雨露多，扁舟又喜泛沧波。","冥冥鸟背夕阳暮，千里月明闻棹歌。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其三","f":"七言绝句","c":["霄汉银河接潞河，诸公同此沐恩波。","于今又遂归宁愿，渐近家山喜气多。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其四","f":"七言绝句","c":["万家城郭通州市，十里帆樯潞水船。","清晓登舻望京国，凤凰楼阁五云边。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其五","f":"七言绝句","c":["波光到底见星辰，中夜行舟月色新。","睡觉水村鸡已唱，云帆清晓过天津。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其六","f":"七言绝句","c":["细草微茫间渚沙，烟林杳霭暗渔家。","舟行不辨东西处，但倚危樯看月华。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其七","f":"七言绝句","c":["舟行暑气正淟涊，岸上行人方郁蒸。","安得长风来万里，顿令烦浊片时醒。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其八","f":"七言绝句","c":["天高云影层层出，野旷河流曲曲长。","百丈牵风晴袅袅，橹声摇月夜茫茫。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其九","f":"七言绝句","c":["两堤草色绿无际，五月草虫声已清。","自是天机能动物，舟中闻此倍多情。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十","f":"七言绝句","c":["堤上閒游眼界宽，青天不尽地漫漫。","此心便觉无拘碍，谁信人间行路难。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十一","f":"七言绝句","c":["天开水面平铺月，风涌潮头倒捲沙。","舟过前村迷远近，一堤杨柳数声鸦。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十二","f":"七言绝句","c":["夹堤杨柳绿依依，傍水人家篱落稀。","小妇携篮卖蒲笋，得钱含笑入荆扉。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十三","f":"七言绝句","c":["水畔人家舟作屋，飘飘身世长儿孙。","几回睡足芦花月，又引帆樯过别村。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十四","f":"七言绝句","c":["参透诗禅渐息机，掀髯觅句句还迟。","橹声惊觉船窗梦，遥见青天一鸟飞。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十五","f":"七言绝句","c":["才罢沿流又溯流，关河不尽兴悠悠。","书生别有胸中略，閒看横江万斛舟。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十六","f":"七言绝句","c":["千年宇宙混舆图，万里江河接舳舻。","泽国晚来飞鸟尽，海风吹月上天衢。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十七","f":"七言绝句","c":["芦叶青青潮水平，吴侬摇橹唱歌声。","歌声橹韵随潮去，背立江风无限情。"]},{"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其十八","f":"七言绝句","c":["江北江南一水通，往来舟楫自匆匆。","推篷独坐浑无语，遥见青天日正中。"]},{"t":"酬陈广文送莱","f":"七言绝句","c":["秋圃应知雨露多，嘉蔬分送奈情何。","书生咬得其根味，绝胜金盘荐紫驼。"]},{"t":"早度古峣关","f":"七言绝句","c":["四围山势郁崔嵬，清晓关门傍水开。","一骑秋风扬策度，野花随路送香来。"]},{"t":"由蓼子谷取捷路抵巩黄河北徙有感","f":"七言绝句","c":["此路经过已十年，重来河水变桑田。","西风不尽登临意，又见寒鸦下夕烟。"]},{"t":"王弼墓","f":"七言绝句","c":["四圣千年道久湮，谁从羲画见天真。","先生埋骨邙山后，犹有玄虚误世人。"]},{"t":"宿白马寺人家","f":"七言绝句","c":["白马驼经事已空，断碑残刹见遗踪。","萧萧茅屋秋风里，一夜雨声乡思浓。"]},{"t":"函谷关","f":"七言绝句","c":["嬴秦烈焰掩全齐，谁遣君侯更向西。","关上月明关下路，英雄千古怨晨鸡。"]},{"t":"登平陆城楼四首 其一","f":"七言绝句","c":["独倚危楼日向西，洪河风起浪高低。","中条北去无多路，回首乡关路不迷。"]},{"t":"登平陆城楼四首 其二","f":"七言绝句","c":["断岸奔流万里风，疏林黄叶九秋中。","画阑干外斜阳暮，并作离愁一段浓。"]},{"t":"登平陆城楼四首 其三","f":"七言绝句","c":["客愁偏向九秋多，况复登楼望浊河。","相去弘农才咫尺，苦无一苇暂从过。"]},{"t":"登平陆城楼四首 其四","f":"七言绝句","c":["中条秋色满山城，一上危楼感慨生。","天外黄流来滚滚，扁舟端拟驾长鲸。"]},{"t":"兴让里","f":"七言绝句","c":["岐阳日色正辉辉，才被馀光便息机。","却把争田为弃土，顿令江汉总思归。"]},{"t":"山水小景四首 其一","f":"七言绝句","c":["湖水茫茫浪拍天，春风湖上有人烟。","小楼半在花林内，帘捲青山看钓船。"]},{"t":"山水小景四首 其二","f":"七言绝句","c":["石上长松落午阴，有人松下鼓瑶琴。","南风过处浑无迹，秪见千山万水深。"]},{"t":"山水小景四首 其三","f":"七言绝句","c":["老树苍崖满目秋，水明沙净晚烟收。","如何万里长江内，只见斯人泛一舟。"]},{"t":"山水小景四首 其四","f":"七言绝句","c":["两崖雪罢树无风，泛泛扁舟水月空。","疑是山阴寻戴老，此时清兴正无穷。"]},{"t":"七夕三首 其一","f":"七言绝句","c":["绝怜天上有佳期，汾水西风独夜时。","望断银河仙路远，鹊桥不见度星旗。"]},{"t":"七夕三首 其二","f":"七言绝句","c":["身世浮云无定迹，客中二十四回秋。","故乡此夕逢佳节，閒看星河彻夜流。"]},{"t":"七夕三首 其三","f":"七言绝句","c":["三处三年逢七夕，鄢陵京索晋河汾。","人生是处堪行乐，领取清风对酒樽。"]},{"t":"留别诸友八首 其一","f":"七言绝句","c":["留连冉冉已过夏，离别匆匆又值秋。","酒尽玉壶歌舞散，月明千里照汾流。"]},{"t":"留别诸友八首 其二","f":"七言绝句","c":["多情累月重留连，惆怅西风送别筵。","咫尺江山暂分手，及归应在早花前。"]},{"t":"留别诸友八首 其三","f":"七言绝句","c":["绿树秋风起夕凉，离筵歌舞断人肠。","欲知别后相思切，明月关山满路霜。"]},{"t":"留别诸友八首 其四","f":"七言绝句","c":["楼头钟尽晓风清，南陌殷勤送我行。","十里汾流两岸月，祗应总是别离情。"]},{"t":"留别诸友八首 其五","f":"七言绝句","c":["汾水西风生夕波，离筵忍听唱骊歌。","男儿不洒相思泪，翠袖红裙奈若何。"]},{"t":"留别诸友八首 其六","f":"七言绝句","c":["离鸾别鹤不须愁，暂向中州访旧游。","待我明年二三月，看花同上禹门楼。"]},{"t":"留别诸友八首 其七","f":"七言绝句","c":["扁舟清晓渡汾河，露草风芦两岸多。","却望高城云雾尽，好山一带列青蛾。"]},{"t":"留别诸友八首 其八","f":"七言绝句","c":["锦瑟银筝酒半酣，离情几许旧曾谙。","却怜后夜相思处，三晋山高月正南。"]},{"t":"秋日过洛阳","f":"七言绝句","c":["洛阳城西今又来，飒飒秋风吹客怀。","禾黍荆榛蛩韵切，昔人曾此起楼台。"]},{"t":"中秋对月遣兴","f":"七言绝句","c":["凉露满天秋气清，月光先到客边明。","举杯对影深相属，只有姮娥不世情。"]},{"t":"元夕寄故乡诸友八首 其一","f":"七言绝句","c":["故乡千里隔关河，好景年年客里过。","又见元宵春一度，红灯几点月明多。"]},{"t":"元夕寄故乡诸友八首 其二","f":"七言绝句","c":["乡人新自故乡来，千里鱼书手自开。","闻道家山风景好，玉笙吹月共徘徊。"]},{"t":"元夕寄故乡诸友八首 其三","f":"七言绝句","c":["寂寂闲门掩月华，春街儿女任諠哗。","窗前坐久银灯烬，首首诗成只忆家。"]},{"t":"元夕寄故乡诸友八首 其四","f":"七言绝句","c":["莫道他乡胜故乡，思归一日九回肠。","元宵忽共乡人语，为写新诗寄上庠。"]},{"t":"元夕寄故乡诸友八首 其五","f":"七言绝句","c":["思乡无日不关情，况复春灯对月明。","欲作家书附回使，归心先过洛阳城。"]},{"t":"元夕寄故乡诸友八首 其六","f":"七言绝句","c":["旧说归期已失期，更逢佳节倍相思。","交亲若问今何似，客里春来困酒卮。"]},{"t":"元夕寄故乡诸友八首 其七","f":"七言绝句","c":["中州何事重留连，忆别诸公已半年。","迟我河汾看春色，百花深处酒如泉。"]},{"t":"元夕寄故乡诸友八首 其八","f":"七言绝句","c":["回首乡关入梦频，马蹄踏尽几年春。","客中胆气峥嵘甚，肯把明珠漫赠人。"]},{"t":"题毋处士画梅竹二首 其一","f":"七言绝句","c":["疑是孤山处士家，暗香浮动月初斜。","千红万紫虽无数，独领春魁是此花。"]},{"t":"题毋处士画梅竹二首 其二","f":"七言绝句","c":["湘江两岸鹧鸪啼，翠袖天寒日又西。","可是无人伴幽独，纷纷桃李下成蹊。"]},{"t":"行黄河岸上","f":"七言绝句","c":["苍崖千仞俯黄流，滚滚波声大地浮。","惆怅灵槎无复见，壮怀祗拟付神游。"]},{"t":"看杨花戏作","f":"七言绝句","c":["纷纷拂拂雪花香，旋逐回风过粉墙。","坐困绿阴看未足，无端春思正悠扬。"]},{"t":"题蒲守刘公梅竹二首 其一","f":"七言绝句","c":["谁倾金醴醉仙娥，绰约朱颜总已酡。","莫向风前吹玉笛，恐惊春梦入江波。"]},{"t":"题蒲守刘公梅竹二首 其二","f":"七言绝句","c":["此君老矣势犹豪，新长孙枝节渐高。","好似一门贤父子，清风相倚迥难招。"]},{"t":"韦广文送醯","f":"七言绝句","c":["鼎鼐何堪欠此生，银瓶携送满寒清。","从今肝膈添诗思，肯使酸斋擅大名。"]},{"t":"过贾鲁宅","f":"七言绝句","c":["长平驿是相君家，不见当时富贵花。","只有苍苍乔木在，至今犹宿夕阳鸦。"]},{"t":"长平","f":"七言绝句","c":["行过长平惨旧名，路人犹指昔年坑。","不知当日将军死，地下曾无见赵兵。"]},{"t":"荥阳道中九首 其一","f":"七言绝句","c":["老亲官定覃怀后，游子南来京索时。","舟渡浊河高处望，太行秋碧绕天涯。"]},{"t":"荥阳道中九首 其二","f":"七言绝句","c":["前途十里即温城，暂向村林避郁蒸。","野老多情能款客，呼儿旋撇瓮头清。"]},{"t":"荥阳道中九首 其三","f":"七言绝句","c":["一年几度过黄河，霁景清风此日多。","临流滚滚兴无尽，直欲遥吞万里波。"]},{"t":"荥阳道中九首 其四","f":"七言绝句","c":["河水南边广武山，山头簇簇故城閒。","徘徊不尽千年事，秋草秋花驻马看。"]},{"t":"荥阳道中九首 其五","f":"七言绝句","c":["独寻危坂出高冈，蔓草荆榛古道荒。","谷口人家似仙馆，几间茅屋荫垂杨。"]},{"t":"荥阳道中九首 其六","f":"七言绝句","c":["一上河濆眼界宽，秋风禾黍动秋山。","敖仓甬道不知处，唯见孤云自往还。"]},{"t":"荥阳道中九首 其七","f":"七言绝句","c":["连村绿树乱蝉秋，禾黍离离正满畴。","为爱中州好风景，挥鞭不厌往来游。"]},{"t":"荥阳道中九首 其八","f":"七言绝句","c":["天高地阔鸟云飞，天际凉飙动客衣。","万物生成看未足，满怀清思正微微。"]},{"t":"荥阳道中九首 其九","f":"七言绝句","c":["马上看书意若何，悠悠随处任经过。","举头忽见南山近，爽气清辉倍觉多。"]},{"t":"次刘佥宪见寄韵四首 其一","f":"七言绝句","c":["忆对清阴转午迟，杯行到手欲无辞。","高山流水今何处，鸿雁南来有寄诗。"]},{"t":"次刘佥宪见寄韵四首 其二","f":"七言绝句","c":["开缄忽见右军书，丽句清词惬所需。","何限相思动秋意，蝉声况是晚凉初。"]},{"t":"次刘佥宪见寄韵四首 其三","f":"七言绝句","c":["几年持节道途间，骢马遥遥意气閒。","况有青山随处好，料来诗思未应阑。"]},{"t":"次刘佥宪见寄韵四首 其四","f":"七言绝句","c":["宪府新成小屋居，居中惟贮旧琴书。","希声古道应何似，一榻清风乐自如。"]},{"t":"通鉴","f":"七言绝句","c":["千二年来治乱机，只从理欲辨安危。","若将此鉴为心鉴，三五如何不并归。"]},{"t":"禹门","f":"七言绝句","c":["连山忽断禹门开，中有黄流万里来。","更欲登临穷胜观，却愁咫尺会风雷。"]},{"t":"渡口","f":"七言绝句","c":["两崖陡起束狂澜，南去沙平势渺漫。","长有扁舟依渡口，行人莫道往来难。"]},{"t":"栈道","f":"七言绝句","c":["石岩危柱迭相承，阁道萦回接杳冥。","天上黄流来滚滚，长风五月洒衣清。"]},{"t":"明德宫","f":"七言绝句","c":["碧瓦朱楹白昼閒，金衣宝扇晓风寒。","摩云观阁高如许，长对河流出断山。"]},{"t":"宫前老柏","f":"七言绝句","c":["苍苍老干铸青铜，缕缕香毛引细风。","自是栽培年岁久，托根长近禹王宫。"]},{"t":"看鹤楼二首 其一","f":"七言绝句","c":["石磴盘云到上头，高风五月已惊秋。","眼空四海无纤物，惟见黄河天际流。"]},{"t":"看鹤楼二首 其二","f":"七言绝句","c":["一柱巍峨势独尊，铁崖三面下无根。","偶登绝顶思前事，满目河山孰与论。"]},{"t":"水阁二首 其一","f":"七言绝句","c":["水阁凭空结构牢，苍崖直下俯洪涛。","辘轳牵绠应千尺，还似垂纶钓巨鳌。"]},{"t":"水阁二首 其二","f":"七言绝句","c":["飞楼缥缈架黄流，滚滚波声世界浮。","遍倚阑干忆前事，功成四载几经秋。"]},{"t":"后土祠","f":"七言绝句","c":["一木为桥渡断溪，山风水气冷凄凄。","千年古庙苍崖下，万里河流正在西。"]},{"t":"石龛","f":"七言绝句","c":["古屋纵横半亩馀，只疑神鬼护阴虚。","苍崖直上通元气，点点寒泉滴露珠。"]},{"t":"靖应姜真人庵","f":"七言绝句","c":["靖应真人隐者流，声名往日动宸旒。","功成不在飞升去，禹庙连云桧柏秋。"]},{"t":"题四景四首 其一","f":"七言绝句","c":["云满青山水满溪，绿杨红杏绕幽栖。","抱琴童子随师去，归到桥心日未西。"]},{"t":"题四景四首 其二","f":"七言绝句","c":["水心亭子四山青，亭下荷花照眼明。","我欲唤船杨柳岸，隔溪终日不闻声。"]},{"t":"题四景四首 其三","f":"七言绝句","c":["四山木落晚江空，江上茅斋爽气中。","立尽秋风何处客，矶头日日看飞鸿。"]},{"t":"题四景四首 其四","f":"七言绝句","c":["怪来寒气袭襟裾，忽向高堂见画图。","树老山空江似练，扁舟不受旅人呼。"]},{"t":"题季札挂剑图","f":"七言绝句","c":["心许君侯口未言，归从陵树挂龙泉。","生平负诺知何限，始信当时公子贤。"]},{"t":"题负薪图","f":"七言绝句","c":["自古诗人咏伐檀，山中不道负薪难。","到家远近何须问，行过溪桥路已宽。"]},{"t":"四皓图","f":"七言绝句","c":["雪鬓苍髯识者稀，功成犹自昧先几。","宁知后日纷纷处，却道刘侯计已非。"]},{"t":"睡熟","f":"七言绝句","c":["睡熟不知风大作，到晓犹闻波浪声。","起坐觅纸欲题句，却忆远人无限情。"]},{"t":"纪先人旧游三首 其一","f":"七言绝句","c":["坛树浓阴覆四墙，春深好鸟啭笙簧。","慈亲此日不同听，乐意翻成泪两行。"]},{"t":"纪先人旧游三首 其二","f":"七言绝句","c":["西壑南冈景物幽，先人曾此数追游。","重来不似当时兴，绿草红芳总是愁。"]},{"t":"纪先人旧游三首 其三","f":"七言绝句","c":["先人最爱佳山水，每对清流玩翠微。","俯仰忽成今与昨，看山看水泪沾衣。"]},{"t":"检旧书得先人手迹","f":"七言绝句","c":["素帙窗前自卷舒，忽看先父数行书。","分明笔迹如平日，一字伤心一泪珠。"]},{"t":"题钱舜举山水小景","f":"七言绝句","c":["琪树秋风生早寒，楼台缥缈暮云间。","桥头有客长无事，閒听溪声静看山。"]},{"t":"观太极图二首 其一","f":"七言绝句","c":["敛襟坐久此心虚，静看濂溪太极图。","理在象中元不杂，莫于象外用工夫。"]},{"t":"观太极图二首 其二","f":"七言绝句","c":["一理阴阳及五行，乾坤万物各生成。","莫言真宰元无迹，久向图中露此情。"]},{"t":"春兴三首 其一","f":"七言绝句","c":["客居城市厌喧嚣，举目云林变绿条。","好景一年都已过，何曾散步到西郊。"]},{"t":"春兴三首 其二","f":"七言绝句","c":["怀抱何由一洒然，劳生扰扰故相牵。","城南山色青如许，不到云林又几年。"]},{"t":"春兴三首 其三","f":"七言绝句","c":["又是春风换物华，静观芳意浩无涯。","寄语莺花休怅望，新诗已懒向人誇。"]},{"t":"刘广文携酒饯行","f":"七言绝句","c":["先人馆下老门生，三十年来故旧情。","今日相逢头已白，殷勤载酒问归程。"]},{"t":"过卢沟河有作","f":"七言绝句","c":["乌府新承帝泽覃，又持宪节按湖南。","卢沟桥上瞻都邑，金阙连云倚翠岚。"]},{"t":"出汉口五首 其一","f":"七言绝句","c":["扁舟泛泛野湖平，岸转奔流近汉城。","满目江山如画里，留题多少旧才名。"]},{"t":"出汉口五首 其二","f":"七言绝句","c":["万里长江滚滚来，楚山凝碧树如苔。","扁舟横渡浪花急，一席好风何快哉。"]},{"t":"出汉口五首 其三","f":"七言绝句","c":["汉江南合楚江流，新涨兼天雪浪浮。","黄鹤不来仙已去，舟人犹指旧时楼。"]},{"t":"出汉口五首 其四","f":"七言绝句","c":["万里沧江水自东，武昌烟树晚朦胧。","独持宪节匆匆过，兴忆南楼夜月中。"]},{"t":"出汉口五首 其五","f":"七言绝句","c":["人家楼阁枕江烟，江上危樯泊万船。","欲问当年无故老，青山依旧水连天。"]},{"t":"出汉口至大江追忆往事有感而作","f":"七言绝句","c":["武昌城对汉阳城，城下长江漫漫平。","二十年前曾过此，烟波一望不胜情。"]},{"t":"览嘉鱼图经","f":"七言绝句","c":["閒览嘉鱼县地图，半为山谷半为湖。","生民计业知应薄，祗赖升平雨露馀。"]},{"t":"公安咏古","f":"七言绝句","c":["古砌长衢满绿苔，疏篱多傍水边栽。","欲知何处怀平仲，老竹荒祠风雨来。"]},{"t":"蜀江水涨如黄河江北诸山彷佛太行遣兴而作","f":"七言绝句","c":["蜀江浊比大河黄，江北诸山似太行。","误喜中原应不远，却闻人语是湖襄。"]},{"t":"澧州","f":"七言绝句","c":["秋日秋风澧有兰，碧峰如画水如环。","荆南自古多骚思，长在閒花野草间。"]},{"t":"常德","f":"七言绝句","c":["百里平川古朗州，沅江滚滚向东流。","竹枝留得唐人句，一曲西风碧树秋。"]},{"t":"武陵","f":"七言绝句","c":["万水千山旧武陵，伏波曾此向南征。","只今无复壶头险，击鼓讴歌乐太平。"]},{"t":"次同年赵侍御阻雨韵五首 其一","f":"七言绝句","c":["秋夜萧萧雨未休，碧窗欹枕忆神州。","霜风会见清南徼，未必轺车久滞留。"]},{"t":"次同年赵侍御阻雨韵五首 其二","f":"七言绝句","c":["天使乘骢此暂休，今朝我亦到南州。","柏台孤枕银灯夜，还似当年阻雨留。"]},{"t":"次同年赵侍御阻雨韵五首 其三","f":"七言绝句","c":["瑶树西风透客怀，早秋凉雨压尘埃。","行台壁上留佳句，知是同年揽辔来。"]},{"t":"次同年赵侍御阻雨韵五首 其四","f":"七言绝句","c":["壁上留题见好怀，旋将征袖拂尘埃。","浪游不得逢知己，阻雨今朝独后来。"]},{"t":"次同年赵侍御阻雨韵五首 其五","f":"七言绝句","c":["境入桃源喜满怀，分司衙里绝尘埃。","绣衣壁上题诗日，正是随车好雨来。"]},{"t":"桃源晓行","f":"七言绝句","c":["隔江烟树晓模糊，纵有丹青画不如。","且喜桃源风景好，山行不厌路崎岖。"]},{"t":"宿界亭驿","f":"七言绝句","c":["山月娟娟满户庭，秋虫唧唧四边鸣。","一杯强饮不成乐，坐听山童打二更。"]},{"t":"辰溪次赵子裕韵二首 其一","f":"七言绝句","c":["尽日山行不厌迟，肩舆随处爱秋溪。","路回忽见江头县，风景清幽兴不迷。"]},{"t":"辰溪次赵子裕韵二首 其二","f":"七言绝句","c":["辰阳已觉雁书迟，满目云山接五溪。","秋夜一杯江县酒，醒来乡思不曾迷。"]},{"t":"益阳山行遇雨","f":"七言绝句","c":["云林漠漠雨凄凄，节节危桥曲曲溪。","可是青骢行处稳，满山红叶衬秋泥。"]},{"t":"雪中度风门岭","f":"七言绝句","c":["肩舆千仞历峥嵘，朔雪寒云杳霭中。","远近东西浑不辨，只疑犹未辟鸿濛。"]},{"t":"靖州道中溪水清驶可爱","f":"七言绝句","c":["石淙急泻响奔雷，溅沫跳珠雪涌堆。","正苦荒山劳降陟，且随流水共萦回。"]},{"t":"池边笋生","f":"七言绝句","c":["绿锦池塘春已深，池边青笋欲成林。","贪看物理添新趣，不管滔滔岁月侵。"]},{"t":"遣兴","f":"七言绝句","c":["永日霜台与众疏，相亲惟有圣贤书。","绿云满院苍苔合，自喜能兼吏隐居。"]},{"t":"黔阳春日杂咏六首 其一","f":"七言绝句","c":["满庭落叶似深秋，好鸟鸣时地转幽。","坐对青山才咫尺，会登绝顶望中州。"]},{"t":"黔阳春日杂咏六首 其二","f":"七言绝句","c":["风起杨花满院飞，翠屏门外送清辉。","蛮中好景非吾土，春燕来时客未归。"]},{"t":"黔阳春日杂咏六首 其三","f":"七言绝句","c":["两年三度客黔滨，前是秋冬后是春。","新绿满庭清昼永，好风时复送香尘。"]},{"t":"黔阳春日杂咏六首 其四","f":"七言绝句","c":["弱柳新梅荫户庭，好山门外列青屏。","间关幽鸟鸣春昼，宛似家山把酒听。"]},{"t":"黔阳春日杂咏六首 其五","f":"七言绝句","c":["睡起霜台似水清，晚春风日弄新晴。","笑看蟢子频频集，却忆人家望客情。"]},{"t":"黔阳春日杂咏六首 其六","f":"七言绝句","c":["驻节黔中改岁华，四山重叠绕天涯。","空庭独坐听鸣鸟，拂面春风吹柳花。"]},{"t":"黔阳山中十首 其一","f":"七言绝句","c":["景好宁知是异邦，竹篱茅舍枕沧江。","吏情更有山林趣，绿树门前画戟双。"]},{"t":"黔阳山中十首 其二","f":"七言绝句","c":["星轺玉节万山深，到处溪流足茂林。","雨过瘴烟清似洗，蛮荒不减壮游心。"]},{"t":"黔阳山中十首 其三","f":"七言绝句","c":["尽日江行路不迷，沟塍水满稻秧齐。","参天绿树茅茨小，何处人家叫午鸡。"]},{"t":"黔阳山中十首 其四","f":"七言绝句","c":["山青云白楚天涯，驻节山中白昼迟。","纵是无边清兴好，知音谁与和新诗。"]},{"t":"黔阳山中十首 其五","f":"七言绝句","c":["江村地僻草萋萋，小阁閒登日欲西。","风景不殊云木秀，只嫌中有鹧鸪啼。"]},{"t":"黔阳山中十首 其六","f":"七言绝句","c":["清和时节似中州，江绕茅堂尽日幽。","官况不羁情散诞，坐看云影自悠悠。"]},{"t":"黔阳山中十首 其七","f":"七言绝句","c":["宦情不改读书情，閒爱山林兴致清。","随意时时写佳句，却嫌行处有虚名。"]},{"t":"黔阳山中十首 其八","f":"七言绝句","c":["竹椽茅屋江边静，永日惟应鸟雀飞。","云白天青山万叠，霜台远客正思归。"]},{"t":"黔阳山中十首 其九","f":"七言绝句","c":["花木时光总不穷，青山叠叠水重重。","欲寻真宰元无迹，祗见苍苍一气功。"]},{"t":"黔阳山中十首 其十","f":"七言绝句","c":["草阁南风分外凉，看山面水据胡床。","宦情萧散知何益，身在江湖忆帝乡。"]},{"t":"四月望夜院中作","f":"七言绝句","c":["月照芭蕉叶上明，小阑干外竹林清。","一襟风露凉如洗，似有新秋在户庭。"]},{"t":"对雨遣兴简陈侍御七首 其一","f":"七言绝句","c":["秋雨通宵尽日鸣，柏台双沼涨皆平。","绿荷袅袅欹香柄，细看明珠泻未停。"]},{"t":"对雨遣兴简陈侍御七首 其二","f":"七言绝句","c":["曲阑干外芰荷香，秋雨来时水满塘。","喜与同年骢马客，水心亭上共持觞。"]},{"t":"对雨遣兴简陈侍御七首 其三","f":"七言绝句","c":["南荒久与故人疏，邂逅同年一月居。","共指小塘荷叶底，水添秋雨欲生鱼。"]},{"t":"对雨遣兴简陈侍御七首 其四","f":"七言绝句","c":["同年持斧到南荒，笑指关山满路霜。","一月沅州城里往，听风听雨喜连床。"]},{"t":"对雨遣兴简陈侍御七首 其五","f":"七言绝句","c":["君恰来时我欲归，沅江秋雨正霏霏。","鹓班若问新消息，为说清霜满绣衣。"]},{"t":"对雨遣兴简陈侍御七首 其六","f":"七言绝句","c":["绿萍如锦盖青池，池面高荷静不移。","閒爱小亭听雨坐，恰如湘水系舟时。"]},{"t":"对雨遣兴简陈侍御七首 其七","f":"七言绝句","c":["同年喜有绣衣人，沅水相逢意气亲。","我去君留莫惆怅，边氓快睹晓霜新。"]},{"t":"襄阳雪中杂咏六首 其一","f":"七言绝句","c":["扁舟南渡汉江来，阻雪连朝住宪台。","莫道铁冠官况冷，琼瑶庭下已成堆。"]},{"t":"襄阳雪中杂咏六首 其二","f":"七言绝句","c":["乌台南面郡城高，城外诸山雪乱飘。","胜迹欲追羊叔子，会从岘首踏琼瑶。"]},{"t":"襄阳雪中杂咏六首 其三","f":"七言绝句","c":["空阶密雪下无声，叶落层层盖已平。","尽日戟门清似水，端居谁与论诗情。"]},{"t":"襄阳雪中杂咏六首 其四","f":"七言绝句","c":["堂台高敞四虚寒，窗外萧萧竹万竿。","一夜霜风鸣到晓，散为清响满人间。"]},{"t":"襄阳雪中杂咏六首 其五","f":"七言绝句","c":["襄阳城外雪纷如，散入江流片片虚。","乍有却无迷望眼，只疑神女弄明珠。"]},{"t":"襄阳雪中杂咏六首 其六","f":"七言绝句","c":["少年曾读浩然诗，襄汉风流百世师。","今日雪中清兴好，论文翻恨不同时。"]},{"t":"芭蕉","f":"七言绝句","c":["夫君本自一心空，舒卷如何叶未穷。","自是根株通大化，故教有象显无踪。"]},{"t":"靖州月夜杂咏五首 其一","f":"七言绝句","c":["一节三年久在边，天威咫尺玉阶前。","靖州城里清宵月，应与家山一样圆。"]},{"t":"靖州月夜杂咏五首 其二","f":"七言绝句","c":["参差林影受风斜，坚坐胡床爱月华。","凉露在庭清似水，不知今夕是天涯。"]},{"t":"靖州月夜杂咏五首 其三","f":"七言绝句","c":["城外清江城上楼，满城明月似深秋。","忽思昌子虽痴小，也念阿爷尚远游。"]},{"t":"靖州月夜杂咏五首 其四","f":"七言绝句","c":["未有涓埃荅九天，漫叨官廪过年年。","静思仕学多违性，搔首能无愧往贤。"]},{"t":"靖州月夜杂咏五首 其五","f":"七言绝句","c":["三百年来新郡邑，七千里外古蛮荒。","无私好是中天月，布满清辉一样光。"]},{"t":"夏夜闻钟","f":"七言绝句","c":["翠帷藤簟竹方床，孤枕慵便五夜凉。","梦里不知身作客，忽疑钟响是家乡。"]},{"t":"卢溪冬夜五首 其一","f":"七言绝句","c":["几度官船过武溪，匆匆都未有留题。","今来驻节当寒夜，绛烛红炉兴不迷。"]},{"t":"卢溪冬夜五首 其二","f":"七言绝句","c":["曲曲清江节节山，霜台分外朔风寒。","寸心祗与梅争白，颇觉苍颜称铁冠。"]},{"t":"卢溪冬夜五首 其三","f":"七言绝句","c":["江县萧条岁欲除，溪山寥落野人居。","九重时复行宽令，使者徵求忍蠹渔。"]},{"t":"卢溪冬夜五首 其四","f":"七言绝句","c":["夜深风雪响侵门，绣被熏来睡正温。","忽念中林有樵者，独惭馀煖未能分。"]},{"t":"卢溪冬夜五首 其五","f":"七言绝句","c":["久客霜风入缊袍，壮心犹倚剑吹毛。","武溪溪上乌台夜，猛虎一声山月高。"]},{"t":"重题五友五首 其一 竹","f":"七言绝句","c":["长日无风亦自清，疏篁况复满秋声。","几回睡醒窗前月，疑是瑶阶佩玉鸣。"]},{"t":"重题五友五首 其二 兰","f":"七言绝句","c":["几载栽培雨露深，好风披拂正关心。","瑶琴一曲凭谁写，惟有宣尼解此音。"]},{"t":"重题五友五首 其三 莲","f":"七言绝句","c":["朝来微雨湿胭脂，并倚新妆照绿池。","莫使香尘涴颜色，深情还有正人知。"]},{"t":"重题五友五首 其四 梅","f":"七言绝句","c":["花正开时节已过，祗留清影弄檐阿。","潇湘千里客归去，想忆花时思更多。"]},{"t":"重题五友五首 其五 菊","f":"七言绝句","c":["未到高秋有别情，新丛簇簇傍阶生。","归心不待花重发，留与新知作眼明。"]},{"t":"董公二首 其一","f":"七言绝句","c":["席捲三秦赤帜东，力陈大义讨元凶。","董公筹略应无敌，萧相虚当第一功。"]},{"t":"董公二首 其二","f":"七言绝句","c":["纷纷豪杰欲兴刘，缟素应为第一筹。","何事元功盟带砺，丹书不到董公侯。"]},{"t":"又题五友五首 其一 竹","f":"七言绝句","c":["三年乌府长琅玕，粉箨新梢次第看。","今日成林足风雨，坐听清响彻云端。"]},{"t":"又题五友五首 其二 梅","f":"七言绝句","c":["红白双梅户外横，看花看叶兴俱清。","今秋只恐归期近，重叠题诗寄别情。"]},{"t":"又题五友五首 其三 莲","f":"七言绝句","c":["镜里芙蓉一色开，高荷倚醉好风来。","采芳谁识心如洗，持赠聊同驿使梅。"]},{"t":"又题五友五首 其四 兰","f":"七言绝句","c":["几岁南州老铁冠，霜台底物可为欢。","祗应九畹滋新种，时采幽香满把看。"]},{"t":"又题五友五首 其五 菊","f":"七言绝句","c":["簇簇新丛傍宪台，台端有客日徘徊。","归期若在花前发，留向新知次第开。"]},{"t":"怀沅州五友五首 其一 竹","f":"七言绝句","c":["劲节虚心独耐看，霜台三载伴清欢。","今朝朔北遥相忆，谁与萧萧共岁寒。"]},{"t":"怀沅州五友五首 其二 梅","f":"七言绝句","c":["正是花时远别离，绮窗应已发新枝。","蓟南腊月霜如雪，相对长吟有所思。"]},{"t":"怀沅州五友五首 其三 菊","f":"七言绝句","c":["几簇芳根遍小台，自呼童子看浇培。","沅江回首深如许，纵有清香亦自衰。"]},{"t":"怀沅州五友五首 其四 兰","f":"七言绝句","c":["频除恶草惜佳丛，笑采幽香岁岁同。","一自沅江骚佩远，小阑谁倚看光风。"]},{"t":"怀沅州五友五首 其五 莲","f":"七言绝句","c":["方塘红锦日熹微，绝爱天葩照客衣。","几赋新诗去雕饰，相思重觉赏心违。"]},{"t":"又怀五友五首 其一 莲","f":"七言绝句","c":["谁识当年周茂叔，爱莲别是一般心。","沅州宪府花如锦，回首蛮山万叠深。"]},{"t":"又怀五友五首 其二 菊","f":"七言绝句","c":["铁冠不受晚风寒，采得幽香静处看。","幸自托根今得所，栽培应有露团团。"]},{"t":"又怀五友五首 其三 兰","f":"七言绝句","c":["九畹曾怀楚客骚，不堪沅澧去人遥。","多情只有当时佩，别后清香尚未消。"]},{"t":"又怀五友五首 其四 梅","f":"七言绝句","c":["红白沅州有二梅，年年长是近春开。","飘廊点砌今谁惜，祗有东风扫石苔。"]},{"t":"又怀五友五首 其五 竹","f":"七言绝句","c":["柏台清绝爱疏茎，踏影攀枝绕砌行。","卫水舟中风雪夜，梦回疑是打窗声。"]},{"t":"博浪沙","f":"七言绝句","c":["大眼由来视独夫，恳怀忠义报凶渠。","英谋已自输曹沫，只恨当时中副车。"]},{"t":"院中杨柳","f":"七言绝句","c":["去日庭中始见栽，既成林后客归来。","春风摆尽轻狂絮，留得清阴满宪台。"]},{"t":"朝回行堤上","f":"七言绝句","c":["御沟行处早春回，春水平堤不起埃。","柳绿蒲青无限好，客边襟抱一时开。"]},{"t":"简焦李罗刘四侍御五首 其一","f":"七言绝句","c":["绿柳红葵满宪台，几陪簪笏共徘徊。","昨朝一别长官去，直到新年院里来。"]},{"t":"简焦李罗刘四侍御五首 其二","f":"七言绝句","c":["文明门外水悠悠，妓子归来雨打头。","却笑道人心似铁，久无飞梦到青楼。"]},{"t":"简焦李罗刘四侍御五首 其三","f":"七言绝句","c":["铁扇都门镇日开，无风车马也尘埃。","雷公不吝连朝雨，洗尽炎蒸一快哉。"]},{"t":"简焦李罗刘四侍御五首 其四","f":"七言绝句","c":["每忆清谈对数公，别来无日不从容。","少陵自是能诗者，却笑樽中酒屡空。"]},{"t":"简焦李罗刘四侍御五首 其五","f":"七言绝句","c":["黄榜同年双进士，青毡并榻两先生。","四君高论应难及，别后深知鄙吝萌。"]},{"t":"读刘靖脩黄金台诗","f":"七言绝句","c":["贤者何曾为此来，黄金空复垒高台。","先生志节超千古，一曲清风溢九垓。"]},{"t":"再怀沅州五友五首 其一","f":"七言绝句","c":["沅阳清气满乌台，为有脩篁绕户栽。","两载好风明月夜，新诗谁对此君裁。"]},{"t":"再怀沅州五友五首 其二","f":"七言绝句","c":["无端诗兴远谁添，红白双梅倚画檐。","千里中州风雪夜，一窗清月忆湘南。"]},{"t":"再怀沅州五友五首 其三","f":"七言绝句","c":["帘捲秋风绕砌花，沅阳几对昔年华。","关山白露三千里，谁采金英泛紫霞。"]},{"t":"再怀沅州五友五首 其四","f":"七言绝句","c":["持赠曾同驿使梅，纫香聊尔意徘徊。","当时九畹花应在，几向光风烂漫开。"]},{"t":"再怀沅州五友五首 其五","f":"七言绝句","c":["薜荔阑边绿锦池，竹亭深坐晚凉时。","忽成远道空劳想，秀色天香发向谁。"]},{"t":"汾上春行","f":"七言绝句","c":["清汾信马踏春酣，汀草萋萋陇麦蔪。","正是煖风啼鸟日，水村花坞似江南。"]},{"t":"骤寒","f":"七言绝句","c":["晓起题诗砚有冰，苦寒端欲诉玄冥。","却思持节荆南道，腊月湖山草色青。"]},{"t":"河南将归","f":"七言绝句","c":["我忆汾南田舍好，绿槐如盖拥高门。","南园旧种双桐树，应有孙枝到碧云。"]},{"t":"忽忆","f":"七言绝句","c":["忽忆巩东峰子岭，入云遥见大河流。","中原胜槩皆堪赋，揽辔还当遂壮游。"]},{"t":"汾河南岸看杏花二首 其一","f":"七言绝句","c":["两载东风看杏花，汾河南岸水西斜。","几回驻马怜秾艳，只恐春流泛落霞。"]},{"t":"汾河南岸看杏花二首 其二","f":"七言绝句","c":["汾水南边锦作堆，连朝相报杏花开。","东风好景休虚掷，一日须来一百回。"]},{"t":"过寿阳用韩文公韵","f":"七言绝句","c":["征骑鸡鸣发大安，山深五月尚风寒。","寿阳举目孤城近，东岭金乌烂晓团。"]},{"t":"宪台斋宿","f":"七言绝句","c":["宪台斋宿几连宵，绛烛银炉伴阒寥。","斗帐梦回更漏永，只听窗外冷风飘。"]},{"t":"喜雨杂咏简院长诸公八首 其一","f":"七言绝句","c":["圣明端拱太平时，好雨当春细若丝。","应是柏台添气象，旋滋花柳更催诗。"]},{"t":"喜雨杂咏简院长诸公八首 其二","f":"七言绝句","c":["正是阳和溥万方，知时好雨润群芳。","趣朝共睹天颜悦，应喜斯民乐泰康。"]},{"t":"喜雨杂咏简院长诸公八首 其三","f":"七言绝句","c":["霏霏朝雨润彤庭，恭逐鹓行谒圣明。","白玉桥边鸣佩过，御沟春水一时生。"]},{"t":"喜雨杂咏简院长诸公八首 其四","f":"七言绝句","c":["御沟新柳湿鹅黄，佩马朝回雨露香。","柏府文书春日静，相过唯觉和诗忙。"]},{"t":"喜雨杂咏简院长诸公八首 其五","f":"七言绝句","c":["柏台春静昼厌厌，好雨如丝不捲帘。","最是东君能借力，閒庭草色一时添。"]},{"t":"喜雨杂咏简院长诸公八首 其六","f":"七言绝句","c":["雨过西山翠欲流，葱葱佳气满神州。","书生莫笑今霜鬓，骏马看花已偿游。"]},{"t":"喜雨杂咏简院长诸公八首 其七","f":"七言绝句","c":["圣主龙飞第一春，天垂雨露万方匀。","苍生坐见跻仁寿，自昔赓歌有舜臣。"]},{"t":"喜雨杂咏简院长诸公八首 其八","f":"七言绝句","c":["万国同心奉至尊，斯民重见饮衢樽。","欲知和气薰天地，只在三春雨露恩。"]},{"t":"发通津驿三首 其一","f":"七言绝句","c":["六月官船发潞阳，水村烟树共微茫。","天门忽已如天上，秪见青山一带长。"]},{"t":"发通津驿三首 其二","f":"七言绝句","c":["新捧天书带紫泥，又承恩旨按三齐。","通津南下波连海，渺渺风帆去似飞。"]},{"t":"发通津驿三首 其三","f":"七言绝句","c":["五色天书出禁中，儒臣将命按三东。","沧波南下通洙泗，鱼跃鸢飞总帝功。"]},{"t":"宿临清薇省行馆","f":"七言绝句","c":["薇垣潇洒九秋天，风叶敲窗夜月圆。","有客乘骢来借宿，新诗留作赁房钱。"]},{"t":"泉林寺","f":"七言绝句","c":["日午停骖暑气收，参天古木乱蝉秋。","绝怜好景添清兴，为写新诗纪胜游。"]},{"t":"梦与陈侍御话旧","f":"七言绝句","c":["分司相见是京华，风节山东向骇誇。","邂逅不知身是梦，觉来秋两溅窗纱。"]},{"t":"菊开忆去秋同官台中共赏","f":"七言绝句","c":["去年客里遇重阳，曾与同官摘晚香。","今日分符行郡邑，独将远意看秋芳。"]},{"t":"嘉祥分司元宵","f":"七言绝句","c":["行台北面是苍山，古柏风生分外寒。","又值元宵春一度，谩烧红烛伴清欢。"]},{"t":"钜野道中","f":"七言绝句","c":["钜野茫茫远际天，春风春雨淡春烟。","河流尚自成陈迹，俯仰千年事落然。"]},{"t":"题汶上分司二小柏","f":"七言绝句","c":["霜台对植长新枝，翠叶交承雨露滋。","直干总应无曲处，稚年俱有栋梁姿。"]},{"t":"闻蛙有怀","f":"七言绝句","c":["春晚乘骢驻德平，古城墙外有蛙鸣。","却思青草池塘夜，三载湖南厌此声。"]},{"t":"暮春道中见桃花尚开","f":"七言绝句","c":["马穿新绿过园林，已恨秾芳误赏心。","犹有小桃花未落，独留馀艳到春深。"]},{"t":"邹平分司杂咏二首 其一","f":"七言绝句","c":["行台独坐听鸣鸠，乔木参天五月秋。","举目好山青未了，应随马足遍东州。"]},{"t":"邹平分司杂咏二首 其二","f":"七言绝句","c":["树绕行廊散碧阴，莺啼小圃送清音。","葵花无数开如锦，解是倾阳共此心。"]},{"t":"临淄道中","f":"七言绝句","c":["平郊漫漫树依依，人物千年总已非。","多少荒台芳草合，不知何处是三归。"]},{"t":"青州分司榴花","f":"七言绝句","c":["石榴小萼未开时，浑似红樱压翠枝。","照日含风千万朵，故园千里正相思。"]},{"t":"穆陵关夜雨","f":"七言绝句","c":["万山绝顶穆陵关，一上山楼五月寒。","烟树满川浮瞑色，晚风吹雨湿阑干。"]},{"t":"胶州","f":"七言绝句","c":["几点青螺海上山，参差楼阁海天宽。","行台五月不知暑，秪觉侵人海气寒。"]},{"t":"栖霞见青桃","f":"七言绝句","c":["来日红桃尚有花，青桃如弹过栖霞。","无端马首还东去，直看青山到海涯。"]},{"t":"栖霞行台夏日","f":"七言绝句","c":["四山环绕柏台深，绿树浓交户外阴。","还似湖南持宪节，坐听山鸟弄清音。"]},{"t":"望岳","f":"七言绝句","c":["揽辔西来过泰安，拂空青霭掠征鞍。","东还算是初冬日，拟上天门次第看。"]},{"t":"莱芜怀古","f":"七言绝句","c":["清节谁能似范丹，清名千载重人间。","莱芜县里停骖日，坐对南山秋色寒。"]},{"t":"再咏汶上分司二小柏","f":"七言绝句","c":["一回相见一回高，夹砌行看翠叶交。","伟器定如房与杜，相期耸壑更昂霄。"]},{"t":"鱼台分司","f":"七言绝句","c":["翠竹红榴掩映间，柏台清昼鸟声閒。","情知物理相关处，心与乾坤一样宽。"]},{"t":"三咏汶上分司二小柏","f":"七言绝句","c":["高标离立入檐长，已有清阴近画堂。","别后又看新子结，风生满院散天香。"]},{"t":"题松鹤图","f":"七言绝句","c":["忽惊虚室起潜蛟，云气阴森爽气飘。","霜雪不知几千古，长年惟有鹤来巢。"]},{"t":"临朐分司四小柏二首 其一","f":"七言绝句","c":["解是平生独爱材，新移四柏后堂栽。","悬知数百年来后，应有清阴满宪台。"]},{"t":"临朐分司四小柏二首 其二","f":"七言绝句","c":["四柏移来拱把馀，一行分植傍阶除。","故应雨露均培养，直干争看耸碧虚。"]},{"t":"简黄仲芳大参三首 其一","f":"七言绝句","c":["正统四年秋九月，天官门下识君时。","神都第一科中客，接踵青云愧后期。"]},{"t":"简黄仲芳大参三首 其二","f":"七言绝句","c":["雅量每期黄淑度，正人应愧薛居州。","斯文四海知同调，且喜京华并辔游。"]},{"t":"简黄仲芳大参三首 其三","f":"七言绝句","c":["天衢连日踏尘埃，忽听萧萧夜雨来。","明日况逢重九节，好怀应为大参开。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其一 小亭花雨","f":"七言绝句","c":["小结茅亭垒石台，绕亭时雨百花开。","一襟道气清如许，更挹幽香满座来。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其二","f":"七言绝句","c":["曾过君家饮小亭，醉看红雨湿春馨。","别来生意应如昨，长对东风阅圣经。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其三 夹道槐云","f":"七言绝句","c":["夹道槐根孔世家，两行飞盖影欹斜。","要承浓渥千年荫，不爱秋黄八月花。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其四","f":"七言绝句","c":["数仞宫墙一路深，屯云交翠落青阴。","红尘十丈知何处，秪引薰风养道心。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其五 兰阶清露","f":"七言绝句","c":["零露瀼瀼带晓浓，绕阶晴霁转光风。","云仍对此琴三弄，还与宣尼古调同。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其六","f":"七言绝句","c":["九畹移来遍孔家，芳丛时遣石阑遮。","故应天意怜香洁，玉露年年润好花。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其七 桐井甘泉","f":"七言绝句","c":["千章嘉树古梧森，一窟寒泉碧甃深。","静扫浓阴汲脩绠，清泠长是涤尘心。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其八","f":"七言绝句","c":["树环嘉木桐阴合，井冽寒泉地脉通。","彩凤九霄应有待，道源千古自无穷。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其九 海棠缀锦","f":"七言绝句","c":["长笑时人爱海棠，芳姿何事近宫墙。","自缘要识东风面，任遣花神缀锦妆。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十","f":"七言绝句","c":["绿烟初散锦霞空，绰约仙人半醉中。","莫怪海棠颜色丽，等閒红紫尽春风。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十一 萱草堆金","f":"七言绝句","c":["绿带春深近北堂，更看红锦烂天香。","国风千古遗诗在，对此应知百虑忘。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十二","f":"七言绝句","c":["自是春风造化机，织成锦翠烂相依。","细看一种生生意，真宰无言识者稀。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十三 松窗皓月","f":"七言绝句","c":["拂窗凉籁起秋声，绮席流光皓月明。","却忆邹轲谈夜气，此时心迹已双清。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十四","f":"七言绝句","c":["画堂松月夜窗虚，宴坐澄心一卷书。","莫道画前元有易，静中天理亦森如。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十五 竹坞凉风","f":"七言绝句","c":["半亩琅玕出短墉，煖烟轻雾碧阴重。","开门净扫苍苔坐，细叶萧萧引好风。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十六","f":"七言绝句","c":["戴雨含烟一径幽，每从长夏数追游。","浓阴深处不知暑，秪觉凉风似水流。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十七 苔石叠翠","f":"七言绝句","c":["山骨移来带藓痕，层峦叠巘势飞翻。","杏花坛里三春雨，疑是岩间一片云。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十八","f":"七言绝句","c":["气通霄汉润通泉，融结还从太古年。","数点青螺云起处，散为霖雨遍山川。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其十九 花圃繁红","f":"七言绝句","c":["煖云无力趁东风，小圃芳菲一径通。","若问人间真太极，便应携手看春红。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其二十","f":"七言绝句","c":["参天乔木圣公家，应爱春风满圃花。","还似濂溪窗外草，一般生意浩无涯。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其二十一 古墙秀柏","f":"七言绝句","c":["曲阜城中夫子墙，墙头老柏正苍苍。","托根终古同元气，未许抡材作栋梁。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其二十二","f":"七言绝句","c":["根蟠厚地干参天，还合宫墙不记年。","遥想杏坛传道日，唯应此木见三千。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其二十三 方沼瑞莲","f":"七言绝句","c":["珍重当年太极翁，曾将道笔写清通。","孔门自是传心者，还向方池看夏红。"]},{"t":"十二景为衍圣公孔彦缙赋二十四首 其二十四","f":"七言绝句","c":["玉井空传太华峰，何如方沼看新红。","浇培更有如船藕，渣滓都归浑化中。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其一","f":"七言绝句","c":["行台西接大明湖，细柳新荷入画图。","海石风光今古意，品题殊觉少陵孤。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其二","f":"七言绝句","c":["独宿行台暑气清，清吟已觉动高情。","令人苦忆黄诗伯，肯许连床听雨声。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其三","f":"七言绝句","c":["杨柳阴阴宪府深，读书因见圣贤心。","钟期去后今千载，谁复人间是赏音。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其四","f":"七言绝句","c":["猎猎风蒲水满塘，轻阴微雨芰荷香。","偶来乘兴观时物，徐步芳洲趁晚凉。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其五","f":"七言绝句","c":["烟笼庭树水侵阶，隐隐轻云细雨来。","爽气已添烦暑退，好怀千古一时开。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其六","f":"七言绝句","c":["绿柳红葵满宪台，清渠碧沼断尘埃。","城头雨过天无际，高鸟孤云自往来。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其七","f":"七言绝句","c":["菰蒲深处水禽鸣，雨过林塘晚更清。","露满碧荷看不定，秪疑仙掌万珠明。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其八","f":"七言绝句","c":["柏台清昼鸟声閒，影落高梧夏日寒。","且喜轻阴天际敛，开门咫尺见南山。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其九","f":"七言绝句","c":["水满方塘盖锦萍，软风高下飏蜻蜓。","清宵雨歇蛙声急，却忆湖湘草色青。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十","f":"七言绝句","c":["万朵红葵折锦苞，新妆相倚斗妖娆。","道人独爱倾阳意，并起丹心忆圣朝。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十一","f":"七言绝句","c":["行台直北是高城，城外溪流面面清。","更拟濠梁寻胜事，观鱼侈有昔人情。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十二","f":"七言绝句","c":["明时叨秩意何如，秪向行台读古书。","自得自歌还自乐，青天白水看鸢鱼。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十三","f":"七言绝句","c":["四月行台暑雨过，方池无数长新荷。","贪观物意归来晚，杨柳薰风到面多。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十四","f":"七言绝句","c":["潇洒流年老铁冠，鬓毛虽白寸心丹。","天书重叠叨天宠，骢马长鸣宇宙宽。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十五","f":"七言绝句","c":["耿耿江湖意不忘，频年草疏奏明光。","行台夏日看时物，最爱葵花向太阳。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十六","f":"七言绝句","c":["忆捧天书别九天，分符频与岁时迁。","行台几度逢佳节，五月薰风入舜弦。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十七","f":"七言绝句","c":["夏雷挟雨急倾盆，风色苍苍晚更昏。","清晓行台看双沼，新荷已没旧波痕。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十八","f":"七言绝句","c":["泰山触石云初起，六合茫茫一雨同。","试听康衢应有颂，调和玉烛圣明功。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其十九","f":"七言绝句","c":["绕屋葵花锦作围，画墙墙外柳依依。","日长庭院游丝静，乳燕穿帘自在飞。"]},{"t":"行台杂咏简黄宪长暨诸宪僚二十首 其二十","f":"七言绝句","c":["万顷平湖接宪台，红莲如锦望中开。","何当与客凌飞阁，更揽山川入壮怀。"]},{"t":"题赵雍画马三首 其一","f":"七言绝句","c":["逸气棱棱不受羁，苍林磨痒立多时。","会应有待王良驭，掣电追风始见奇。"]},{"t":"题赵雍画马三首 其二","f":"七言绝句","c":["白面骊驹汗血乾，风鬃倚树玉蹄攒。","谁人为制青丝络，骑出横门万众看。"]},{"t":"题赵雍画马三首 其三","f":"七言绝句","c":["玉马王孙已入周，曾将绝艺写骅骝。","谩誇有子能传业，不道东陵有故侯。"]},{"t":"读峄山碑","f":"七言绝句","c":["六国平来四海家，相君当代擅才华。","谁知颂德山头石，却与他人戒后车。"]},{"t":"重题临胊行台四柏二首 其一","f":"七言绝句","c":["四柏移栽已二年，重来相对意留连。","时人莫比甘棠树，浅薄惭无惠化传。"]},{"t":"重题临胊行台四柏二首 其二","f":"七言绝句","c":["宪府重来柏渐高，良材元不困蓬蒿。","还应老大惊人目，香叶团空有凤巢。"]},{"t":"重题胶州行台二首 其一","f":"七言绝句","c":["六年三按古胶东，两见葵花五月红。","却忆端阳沾赐扇，曾陪鹓侣觐飞龙。"]},{"t":"重题胶州行台二首 其二","f":"七言绝句","c":["留题今是两端阳，海气仍飘五月凉。","却爱名花当户发，还将远意采幽香。"]},{"t":"四景为李通政赋四首 其一","f":"七言绝句","c":["石桥流水自东西，绿树连云翠嶂低。","却忆当年持宪节，扁舟曾泛武陵溪。"]},{"t":"四景为李通政赋四首 其二","f":"七言绝句","c":["红尘飞不到青山，宛转桥东水閤寒。","立尽夕阳桥上客，看山看水不知还。"]},{"t":"四景为李通政赋四首 其三","f":"七言绝句","c":["木落霜青水不波，野人茅屋带岩阿。","幽林采得怜香洁，坐对南山兴最多。"]},{"t":"四景为李通政赋四首 其四","f":"七言绝句","c":["竹林茅屋枕江皋，叠玉峰峦夹岸高。","似是剡溪清兴发，独冲风雪泛轻舠。"]},{"t":"四景为张给事题四首 其一","f":"七言绝句","c":["云满青山水满溪，百花如锦草萋萋。","少陵诗思知多少，到处娇莺恰恰啼。"]},{"t":"四景为张给事题四首 其二","f":"七言绝句","c":["百尺清潭万仞山，山围水閤下虚寒。","道人已自无焦火，况在山光水色间。"]},{"t":"四景为张给事题四首 其三","f":"七言绝句","c":["无边草木不禁霜，只有黄花晚更香。","笑采黄花斟美酒，南山咫尺兴难忘。"]},{"t":"四景为张给事题四首 其四","f":"七言绝句","c":["仙家楼观郁嵯峨，雪岭冰溪眼底过。","驴背探春春信早，诗情不必灞桥多。"]},{"t":"斋宿杂咏十首 其一","f":"七言绝句","c":["高堂灯火夜相亲，点检诗书忆古人。","自愧久持三尺法，一生长保寸心春。"]},{"t":"斋宿杂咏十首 其二","f":"七言绝句","c":["霜竹风寒夜向深，灯前读易见天心。","京华又是逢长至，坐忆尧夫子半吟。"]},{"t":"斋宿杂咏十首 其三","f":"七言绝句","c":["再入霜台持宪节，又承丹诏育菁莪。","只今理寺通朝籍，倍觉天恩滚滚多。"]},{"t":"斋宿杂咏十首 其四","f":"七言绝句","c":["灯花静夜结金虫，炉火其如树杪风。","小阁有春应自省，此心期与万人同。"]},{"t":"斋宿杂咏十首 其五","f":"七言绝句","c":["法从追陪二十年，寸心期不愧先贤。","士师自是庭坚职，尚忆虞廷咏敕天。"]},{"t":"斋宿杂咏十首 其六","f":"七言绝句","c":["马蹄频踏暮街尘，理寺归来月色新。","静室有心空自省，忘言相对是何人。"]},{"t":"斋宿杂咏十首 其七","f":"七言绝句","c":["金门待漏三更月，玉陛趋朝五色云。","补衮即非樗散质，微诚长祝圣明君。"]},{"t":"斋宿杂咏十首 其八","f":"七言绝句","c":["迹忝鹓行第几班，朝回马上看西山。","雪崖冰谷清如许，咫尺烟霞未可攀。"]},{"t":"斋宿杂咏十首 其九","f":"七言绝句","c":["待伴未消窗外雪，宜人偏爱竹间风。","斋居已自心如洗，况与寒宵此景同。"]},{"t":"斋宿杂咏十首 其十","f":"七言绝句","c":["都城钟鼓夜深沈，棘寺灯前有客吟。","不是少陵耽丽句，虚台元是发清音。"]},{"t":"题陈希夷图","f":"七言绝句","c":["白云回首是三峰，宴坐苍苔睡正浓。","人世红尘浑断绝，野花啼鸟自春风。"]},{"t":"题枯木竹石四首 其一 野渚春容","f":"七言绝句","c":["荒溪野渚曲流通，苍翠巑岏淑气中。","潇洒一般春意思，纷纷红紫挹高风。"]},{"t":"题枯木竹石四首 其二 临波春意","f":"七言绝句","c":["苍玉生苔浸绿波，新篁老木散枝柯。","徒劳人世歌招隐，淡荡东风野兴多。"]},{"t":"题枯木竹石四首 其三 淡霭凉生","f":"七言绝句","c":["扁舟几度泛湘波，老木疏篁翠石多。","凉吹淡烟图画里，远怀清绝奈秋何。"]},{"t":"题枯木竹石四首 其四 萧骚霁雪","f":"七言绝句","c":["山间昨夜雪三尺，晓云如拭天无痕。","怪得清声满人世，石林冻竹风翻翻。"]},{"t":"绝句三首 其一","f":"七言绝句","c":["一室无尘静有馀，清风频度小窗虚。","韦编读罢心如水，閒看浮云自捲舒。"]},{"t":"绝句三首 其二","f":"七言绝句","c":["扰扰征途二十年，萧萧短发赋归田。","青山绿水都如旧，得失升沉事落然。"]},{"t":"绝句三首 其三","f":"七言绝句","c":["早知大道心无外，始觉身閒乐有馀。","一卷陶诗千载兴，悔将名利役慵疏。"]},{"t":"绝句四首 其一","f":"七言绝句","c":["疏懒经旬不出门，炎风暑气任昏昏。","饥餐渴饮披书卷，高卧开窗看白云。"]},{"t":"绝句四首 其二","f":"七言绝句","c":["忆昔曾游海上山，夏云冬雪满征鞍。","如今嬴得身无事，一榻清风白昼閒。"]},{"t":"绝句四首 其三","f":"七言绝句","c":["长江风起浪如山，驿路红尘几往还。","三十年前回首处，烟蓑依旧钓矶閒。"]},{"t":"绝句四首 其四","f":"七言绝句","c":["年少争名老可羞，青山绿水去来休。","是非得失何须问，已是忘机伴白鸥。"]},{"t":"汾上春日二首 其一","f":"七言绝句","c":["道边桃李绿阴繁，花落难招万片魂。","只有清汾流不尽，年年长是绕孤村。"]},{"t":"汾上春日二首 其二","f":"七言绝句","c":["汾水春流岸岸深，水村新绿满春林。","残红已逐东风尽，不道游人负赏心。"]},{"t":"宿青桥驿听江声","f":"七言绝句","c":["青桥驿近黑龙江，江上滩声暗入窗。","高枕才眠过夜半，惊回旅梦正淙淙。"]},{"t":"草凉楼驿","f":"七言绝句","c":["翠华西幸驻山间，草阁乘凉动喜颜。","何似长安歌舞地，凤楼千尺更高寒。"]},{"t":"朝天驿","f":"七言绝句","c":["征骖行尽褒南道，又上朝天驿畔舟。","两岸云林青未了，嘉陵南去水悠悠。"]},{"t":"盆池鱼","f":"七言绝句","c":["浮游南北与西束，不出区区斗水中。","何似巨鳞居大海，波涵天地浪摇风。"]},{"t":"泛川江有感","f":"七言绝句","c":["双亲未老我童年，曾泛岷江六月船。","今日重来泛江水，我衰亲没泪潸然。"]},{"t":"夏夜宿龙瓜驿","f":"七言绝句","c":["风树飕飗雨不休，夜眠江馆似深秋。","梦回忽见窗前烛，驿吏催人又放舟。"]},{"t":"效竹枝歌三首 其一","f":"七言绝句","c":["锦官城东多水楼，蜀姬酒浓消客愁。","醉来忘却家山道，劝君莫作锦城游。"]},{"t":"效竹枝歌三首 其二","f":"七言绝句","c":["江上小楼开户多，蜀侬解唱巴渝歌。","清江中夜月如昼，楼头贾客奈乐何。"]},{"t":"效竹枝歌三首 其三","f":"七言绝句","c":["杨柳昽昽天欲明，锦江夜雨江水生。","盐船无数恶年少，閒上江楼看晓晴。"]},{"t":"却赠","f":"七言绝句","c":["有人情重赠尤多，奈我中心义理何。","纵使尽添齐楚富，一身之外总为他。"]},{"t":"放船","f":"七言绝句","c":["野旷天低江面平，放船东下好风清。","江天况值新晴霁，云白山青望眼明。"]},{"t":"江行","f":"七言绝句","c":["两岸好山看不尽，一江烟水去无穷。","谁人为和沧浪曲，兴在空濛杳霭中。"]},{"t":"平羌望峨眉山","f":"七言绝句","c":["峨眉画出天边秀，青到平羌尚未休。","山月半轮怀李白，扁舟我亦下渝州。"]},{"t":"读史二首 其一","f":"七言绝句","c":["汉唐末事谁能鉴，晋宋当年世所知。","犹有一编青史在，悠悠长使后人悲。"]},{"t":"读史二首 其二","f":"七言绝句","c":["东言来若用言难，不用忠言亦等閒。","若信当时江统论，定无戎马到长安。"]},{"t":"除夜","f":"七言绝句","c":["又逢除夜客西川，银烛金炉白发前。","却忆去年京邸夜，朝衣新试候朝天。"]},{"t":"蜀中元夕","f":"七言绝句","c":["京华西蜀两元宵，总去家山道路遥。","来岁乞归逢此夕，故乡灯火沸笙箫。"]},{"t":"成都看梨花","f":"七言绝句","c":["锦城风煖不生尘，开遍梨花万树春。","吹散绿云帘尽捲，广寒宫里有仙人。"]},{"t":"看木瓜花","f":"七言绝句","c":["杏艳桃夭二月终，好花难比木瓜红。","回头总愧青青柏，生怕林间一夜风。"]},{"t":"咏史","f":"七言绝句","c":["平吴四海尽为家，内苑新添万树花。","秪喜羊车游别院，不堪轵道驾牛车。"]},{"t":"戏题则天乡","f":"七言绝句","c":["无端险恶山川气，尽付当时武媚娘。","淫虐千年遗臭在，至今人唾则天乡。"]},{"t":"纪行口号","f":"七言绝句","c":["襄阳曾渡汉江水，嶓冢还寻汉水源。","自笑苦无经济略，道途何事往来烦。"]},{"t":"自朝天驿回京","f":"七言绝句","c":["去春舟发朝天驿，今夏朝天岭上回。","水陆朝天行已遍，朝天从此上金台。"]},{"t":"太常许卿送菜戏简十首 其一","f":"七言绝句","c":["为谢东邻许太常，嘉蔬频送意难忘。","呼童带叶连根煮，咬得其中一味长。"]},{"t":"太常许卿送菜戏简十首 其二","f":"七言绝句","c":["摘送园蔬露未乾，齑成新味带咸酸。","几回放箸诗肠饱，绝胜先生苜蓿盘。"]},{"t":"太常许卿送菜戏简十首 其三","f":"七言绝句","c":["空堂养病似斋居，喜送东园几种蔬。","吃此久无烹宰事，不须仍用远庖廚。"]},{"t":"太常许卿送菜戏简十首 其四","f":"七言绝句","c":["白发青袍老寺丞，卜居喜近太常卿。","故知气味多相似，频送东园菜把青。"]},{"t":"太常许卿送菜戏简十首 其五","f":"七言绝句","c":["菜出东园种种新，太卿相送意何亲。","平生自是甘清味，肉食能无愧古人。"]},{"t":"太常许卿送菜戏简十首 其六","f":"七言绝句","c":["园蔬新拔带霜浓，烂煮香根放箸空。","谁识其中有真味，不须苦羡紫驼峰。"]},{"t":"太常许卿送菜戏简十首 其七","f":"七言绝句","c":["自笑官贫气尚豪，党姬休复论羊羔。","卿家能送东园菜，清味还应厌老饕。"]},{"t":"太常许卿送菜戏简十首 其八","f":"七言绝句","c":["此色斯民不可有，此味庙堂不可无。","顾我已非调燮手，先生相送意何如。"]},{"t":"太常许卿送菜戏简十首 其九","f":"七言绝句","c":["雅契名卿柰若何，嘉蔬频送意尤多。","生平味此无厌足，恐似当年吃菜魔。"]},{"t":"太常许卿送菜戏简十首 其十","f":"七言绝句","c":["京华交契似君稀，白首相看意不违。","忽见名园送新菜，故乡老圃倍思归。"]},{"t":"徐州见黄河","f":"七言绝句","c":["吾家正在龙门下，流出黄河几曲长。","忽向徐州城外见，牵情一水正思乡。"]},{"t":"燕子楼","f":"七言绝句","c":["孀妾当时一女流，犹知守节度春秋。","往来忘义忘仁者，莫上彭城燕子楼。"]},{"t":"戏马台","f":"七言绝句","c":["八千兵渡大江来，戏马高台亦壮哉。","何事乌江骓不逝，高台翻使后人哀。"]},{"t":"陵母墓","f":"七言绝句","c":["鹿走中原海起尘，独从草昧识真人。","纷纷都是人间死，母死高名万古新。"]},{"t":"吕梁洪","f":"七言绝句","c":["长洪几折奔流急，乱石两崖还叠重。","被发行游浑不见，往来舟楫自匆匆。"]},{"t":"过淮阳有感而作","f":"七言绝句","c":["武皇侧席正求贤，直道谁居汲黯前。","何事不教留禁闼，淮阳高卧度流年。"]},{"t":"高邮露筋庙二首 其一","f":"七言绝句","c":["高邮女子志何坚，假宿宁论性命全。","甘向荒陂死蚊喙，此生元不愧苍天。"]},{"t":"高邮露筋庙二首 其二","f":"七言绝句","c":["囋血其如利觜何，荒陂一夕死贞娥。","从教筋骨当年露，嬴得清名世不磨。"]},{"t":"渡江","f":"七言绝句","c":["仪真北上念三年，又上江南济渡船。","清晓登舻望京国，钟山彷佛翠云连。"]},{"t":"望南京","f":"七言绝句","c":["虎踞龙蟠入望边，钟山瑞霭翠相连。","仰思圣祖开洪业，定鼎宜过忆万年。"]},{"t":"题双鹊图","f":"七言绝句","c":["梅竹交青映柏枝，飞来双鹊立多时。","主人翁好无弹射，有喜令渠日日知。"]},{"t":"太平门","f":"七言绝句","c":["何处清时快往还，太平门外好湖山。","閒花野草应无数，惟有青松最耐看。"]},{"t":"大理后庭竹林山色二首 其一","f":"七言绝句","c":["钟山雨过翠成堆，竹里清风作阵来。","爱竹看山有真乐，高人远矣忆追陪。"]},{"t":"大理后庭竹林山色二首 其二","f":"七言绝句","c":["閒爱脩篁静爱山，清阴秀色座中看。","老来渐得悠然趣，天际浮云任往还。"]},{"t":"临终口号","f":"七言绝句","c":["土床羊褥纸屏风，睡觉东窗日影红。","七十六年无一事，此心惟觉性天通。"]},{"t":"青城分司暮春","f":"七言绝句","c":["漠漠杨花满院飞，重来又见一春归。","去年记得停骖日，正月庭前雪作围。"]},{"t":"题松竹梅图","f":"七言绝句","c":["翠竹青松共白梅，几枝潇洒出尘埃。","长年自保风霜节，不学春红向煖开。"]},{"t":"濮州道中口号","f":"七言绝句","c":["岁月多从马上过，勋名未立鬓先皤。","风霜满面谁能识，极目苍天一放歌。"]},{"t":"舟发辰溪岸","f":"五言绝句","c":["岸脚插江深，洄潭摇石影。","舟行若天游，妙处心独领。"]},{"t":"静夜","f":"五言绝句","c":["雨滴霜台静，灯明宪府深。","新诗吟谩好，谁复是知音。"]},{"t":"题墨兰二首 其一","f":"五言绝句","c":["已见光风转，应知九畹深。","殷勤采香洁，持慰美人心。"]},{"t":"题墨兰二首 其二","f":"五言绝句","c":["既自充楚佩，还曾入孔琴。","寄言采芳者，云谷莫辞深。"]},{"t":"秋夜","f":"五言绝句","c":["泠泠碧窗风，皎皎疏帘月。","重门掩秋霜，素练捣寒雪。"]},{"t":"荒径","f":"五言绝句","c":["晓行荒径中，瀼瀼草上露。","日出云气收，一鸟空中度。"]},{"t":"夜饮李海昌宅","f":"五言绝句","c":["重门敞春夕，灯烛霭馀辉。","醉我百壶酒，留连夜未归。"]},{"t":"早起","f":"五言绝句","c":["鸡鸣耿不寐，展转待明发。","童子看窗前，犹言有残月。"]},{"t":"早发","f":"五言绝句","c":["晨星耿孤色，晓月馀清朗。","舟人解缆行，梦觉波声响。"]},{"t":"野市","f":"五言绝句","c":["野市二三家，柴门傍水斜。","溪童卖蒲笋，归路不辞赊。"]},{"t":"率成","f":"五言绝句","c":["舟过水无迹，云收天本清。","外物自纷扰，吾心良独明。"]},{"t":"送和司训","f":"五言律诗","c":["秋色满平阴，秋声处处砧。","离筵对衰草，别路绕疏林。","白日青霄迥，红云紫极深。","此行应得意，早晚报佳音。"]},{"t":"久雨遣怀六首 其一","f":"五言律诗","c":["客居连市井，积雨竟朝昏。","屋漏频移榻，泥深少出门。","窗风侵座冷，檐溜入宵繁。","赖有诗驱闷，无劳问酒樽。"]},{"t":"久雨遣怀六首 其二","f":"五言律诗","c":["秋来常苦雨，风气早生寒。","小鸟投林急，高鸿下食难。","奔流淹古道，密雾隐前山。","试诵停云句，中怀独未宽。"]},{"t":"久雨遣怀六首 其三","f":"五言律诗","c":["连日对秋雨，其如客思何。","泥涂宁出户，流潦欲成河。","生菌井阑遍，积苔墙角多。","无由访知己，遣兴且吟哦。"]},{"t":"久雨遣怀六首 其四","f":"五言律诗","c":["泥泞不可出，茅斋静坐时。","怀贤寻往传，课子诵新诗。","近悟柔为胜，深知巧是非。","雨声杂凉吹，萧飒发清机。"]},{"t":"久雨遣怀六首 其五","f":"五言律诗","c":["密雨洒如丝，凉风散漫吹。","泥途殊汨没，茅舍久淋漓。","秋意心先得，虫声耳独知。","田家望收穫，何日静云霓。"]},{"t":"久雨遣怀六首 其六","f":"五言律诗","c":["小窗听雨坐，灯影照孤吟。","谁识无边道，元同不外心。","客襟澄夜气，檐溜滴清音。","诗就无馀和，悠悠思转深。"]},{"t":"寄秉忠周司训二首 其一","f":"五言律诗","c":["良夜对床宿，清晨送子行。","西郊雨新霁，古道马频鸣。","执手别时话，挥鞭独往情。","相思杳难极，鸿雁带秋声。"]},{"t":"寄秉忠周司训二首 其二","f":"五言律诗","c":["过我衡门下，秋宵雨歇初。","繁星随汉阙，明月到窗虚。","别数宁辞酒，谈多不厌书。","今朝远相忆，陡觉鬓毛疏。"]},{"t":"谩成","f":"五言律诗","c":["客里经年久，交游日渐新。","名浮真自愧，知少不生嗔。","大道终非外，微言总是真。","悠然无所竞，转觉快心神。"]},{"t":"陈广文见访","f":"五言律诗","c":["爱客情何厚，肩舆到所居。","樽醪携腊蚁，盘错间春鱼。","雅意忘年契，高怀胜日雩。","剧谈移永昼，未儗促归途。"]},{"t":"挽江处士","f":"五言律诗","c":["处士好静者，放情丘壑间。","樽前流水远，窗外白云閒。","孙子诗书熟，交亲礼数宽。","百年今已矣，凉月满柯山。"]},{"t":"卢沟桥","f":"五言律诗","c":["沙水相荡潏，晴宵飞彩虹。","阑干临极浦，华表撼高风。","爽气西山秀，祥云北阙浓。","南征从北发，归拟驻华骢。"]},{"t":"入湖南界","f":"五言律诗","c":["行尽中州地，湖南境界初。","渐闻人语异，更讶鸟音殊。","溪谷多栽稻，池塘尽养鱼。","山村聊借宿，风月夜堂虚。"]},{"t":"应山道中","f":"五言律诗","c":["万壑岚光满，晓骑骢马行。","茂林交拥盖，脩竹送前旌。","到面溪风冷，经心石涧清。","豺狼应远迹，狐鼠不须惊。"]},{"t":"晚至云梦","f":"五言律诗","c":["云梦行看近，肩舆趁晚凉。","稻塍新穗吐，莲沼落红香。","密树隐茅屋，芜堤系野航。","霜台绝萧洒，容我得徜徉。"]},{"t":"发云梦二首 其一","f":"五言律诗","c":["鞍马几千里，又登云梦舟。","天围平野阔，水入大江流。","笑傲倾樽蚁，微茫听棹讴。","往年怀七泽，今日遂清游。"]},{"t":"发云梦二首 其二","f":"五言律诗","c":["昔闻云梦泽，今泛楚人船。","地远烟迷树，湖平浪拍天。","南风清宪节，北斗烛龙泉。","频向中宵望，武昌何处边。"]},{"t":"大江逢霁景独酌有作","f":"五言律诗","c":["舟行逢霁景，逸兴杳难群。","绿树江边影，青天水底云。","众山连复断，双橹合还分。","自酌樽中酒，微吟到半醺。"]},{"t":"舟发城陵矶","f":"五言律诗","c":["急鼓催舟发，依稀见岳阳。","远波浮岛屿，众水合岷湘。","竹瓦居人閤，杉脾贾客房。","且看风景异，未觉远游伤。"]},{"t":"辰溪晓泛五首 其一","f":"五言律诗","c":["沅水一千里，辰溪又泛舟。","山云合雨暗，身世与天游。","已觉鸡声远，惟闻橹韵幽。","所经多险涉，还似解离忧。"]},{"t":"辰溪晓泛五首 其二","f":"五言律诗","c":["湛湛江流碧，层层石岸高。","蛮讴催健橹，瘴雨洒轻舠。","自勖冰霜操，宁辞旦夕劳。","五溪山万叠，何处是龙标。"]},{"t":"辰溪晓泛五首 其三","f":"五言律诗","c":["怪石双崖峻，秋江一道平。","榜人皆异语，岸鸟亦殊声。","洞户编茅小，蛮舟刳木轻。","虽惊风土异，重喜万方清。"]},{"t":"辰溪晓泛五首 其四","f":"五言律诗","c":["苍峡几千尺，天开万古馀。","波穿石眼瘦，舟压水心虚。","历历瞻奇秀，悠悠想化初。","所希观物妙，难觅邵尧夫。"]},{"t":"辰溪晓泛五首 其五","f":"五言律诗","c":["自有烟霞分，观风任所之。","洞馀槃瓠种，江绕伏波祠。","秋老芙蓉树，云深薜荔丝。","欲知消远思，秪是咏新诗。"]},{"t":"舟发长沙四首 其一","f":"五言律诗","c":["晓溯湘江水，微风漾碧波。","好山随岸远，野烧入林多。","往哲题诗处，今予鼓棹过。","年来游览数，天意遣吟哦。"]},{"t":"舟发长沙四首 其二","f":"五言律诗","c":["已觉长沙北，犹瞻岳麓西。","天浮湘水阔，树入楚山低。","岸芷馀香草，丛篁染旧啼。","昔贤游览地，我亦为留题。"]},{"t":"舟发长沙四首 其三","f":"五言律诗","c":["长沙城下驿，解缆发扁舟。","水栅千家市，沙村十里洲。","喜逢晴霁景，况值太平秋。","宪节叨光宠，怀贤独未休。"]},{"t":"舟发长沙四首 其四","f":"五言律诗","c":["十日长沙住，登舟忆少陵。","花飞有底急，酒美为谁倾。","浩浩当年兴，悠悠此日名。","幸逢明盛世，持斧故南征。"]},{"t":"湘乡道中","f":"五言律诗","c":["湘乡南去路，连日是山行。","地僻溪潭绿，冬和草树荣。","野人悬稻把，古戍列旄旌。","异俗今如此，归当话友生。"]},{"t":"思亲","f":"五言律诗","c":["二亲俱久逝，孤子际明时。","谬忝风霜任，深承雨露私。","光荣宁及养，劬育竟何为。","愿竭涓埃报，焚黄会有期。"]},{"t":"宿湘乡道中山亭纪怀","f":"五言律诗","c":["又是山亭宿，林峦夜杳冥。","天临南岭近，风入北窗清。","开卷求心事，倾壶荡客情。","二亲久辞世，不寐想平生。"]},{"t":"沅州新正书景三首 其一","f":"五言律诗","c":["楚南时节异，正月似深春。","傍砌萱苗长，临池草色新。","江山晴景媚，庭院煖风频。","坐惜梅花落，题诗忆远人。"]},{"t":"沅州新正书景三首 其二","f":"五言律诗","c":["颇讶沅州地，新正景不同。","远山青草瘴，深院落梅风。","角角寻巢鸟，喧喧采蕊蜂。","春衣初试裌，和气满帘栊。"]},{"t":"沅州新正书景三首 其三","f":"五言律诗","c":["楚地春来早，群花次第开。","轻黄舒柳线，重碧染莓苔。","永日香凝篆，和风酒满杯。","端居叨宠渥，何以答涓埃。"]},{"t":"正月十三日夜书","f":"五言律诗","c":["两日是元夕，山城已试灯。","讴歌连夜发，萧鼓遍街鸣。","人喜新风景，时逢旧太平。","柏台谁是伴，梅月正交清。"]},{"t":"遣兴","f":"五言律诗","c":["庭幽多乐趣，向歇爱晴晖。","绿竹生孙早，红梅结子稀。","赋诗新有趣，读易渐知几。","眼镜何空阔，看云天际飞。"]},{"t":"晓上草阁","f":"五言律诗","c":["通宵雷雨骤，晓霁试登楼。","百鸟声相和，双江涨合流。","宁知冀北客，来按楚南州。","满眼波涛急，飘然欲放舟。"]},{"t":"乔口溯流往长沙","f":"五言律诗","c":["楚岫无边翠，湘流不尽清。","香兰屈子赋，苦竹鹧鸪声。","风景当年事，云霞万古情。","沙头旧鸥鸟，谁肯与寻盟。"]},{"t":"武口守风四首 其二","f":"五言律诗","c":["武口丛祠下，维舟几日馀。","北风增骇浪，南客念归途。","水远浮三蜀，烟浓暗五湖。","江村秋雨里，难觅酒家垆。"]},{"t":"武口守风四首 其三","f":"五言律诗","c":["归思方正切，北风何太狂。","江村平隐见，湖树远微茫。","浪起鱼龙伏，天低鹤鹳翔。","貂裘思更著，秋雨早生凉。"]},{"t":"武口守风四首 其四","f":"五言律诗","c":["系舟杨柳驿，风雨苦连朝。","远岸烟埋树，荒村水没桥。","年华身老大，湖海兴萧条。","天意何留滞，应怜望国遥。"]},{"t":"舟中偶成","f":"五言律诗","c":["舟中如斗室，坐卧觉心清。","闭户嫌风冷，推篷爱日明。","偶思前世事，因见古人情。","自顾知何益，诗书浪得名。"]},{"t":"汉江晓泛","f":"五言律诗","c":["城下扁舟发，江清宿雾消。","竹村迎岸出，粉蝶背人遥。","神女无消息，明珠久寂寥。","鹿门看渐近，满耳飒清飙。"]},{"t":"舟中遣闷","f":"五言律诗","c":["五日行不尽，洞庭青草宽。","穷阴连旦夕，密雾隐湖山。","诗思虽难竭，酒壶行复乾。","孤舟亲爱远，何日暂为欢。"]},{"t":"近日收书渐多戏成","f":"五言律诗","c":["元凯真成癖，收书日又多。","静须频检阅，忙不废吟哦。","得意欲谁语，感怀聊自歌。","忘形到尔汝，胶漆岂能过。"]},{"t":"院中遣兴二首 其一","f":"五言律诗","c":["为客知应久，池塘夏景深。","圆荷高倚盖，新笋密成林。","山鸟因时语，阴虫应节吟。","乾坤知帝力，自许一生心。"]},{"t":"院中遣兴二首 其二","f":"五言律诗","c":["片雨过山城，空阶物意清。","黄梅拾又落，翠藓踏还生。","几许催诗景，无端望国情。","蛮方耕事少，乌府但横经。"]},{"t":"夜坐偶书","f":"五言律诗","c":["夜夜烧官烛，时时读我书。","斗牛双古剑，天地一迂儒。","郡邑三苗外，风霜两岁馀。","江湖怀魏阙，似觉鬓毛疏。"]},{"t":"舟中三首 其一","f":"五言律诗","c":["来往虽云数，应无愧此江。","观书心见独，揉橹韵闻双。","岸转山相掩，湍奔石互撞。","裁诗清兴发，晏坐启船窗。"]},{"t":"舟中三首 其二","f":"五言律诗","c":["石底明皆见，清波淡不流。","几年乌府客，一叶楚江舟。","求富知为妄，存心得自由。","所欣安履顺，未必叹淹留。"]},{"t":"舟中三首 其三","f":"五言律诗","c":["好在黔中地，相留过几年。","岸经冬岭树，水宿夜滩船。","支枕思前事，清心忆往贤。","一阳看渐近，吾道故应旋。"]},{"t":"黔江晓泛","f":"五言律诗","c":["五月蛮江涨，官船泛泛轻。","波光一道白，山色两边青。","只有耽书癖，都无报国能。","中原有家室，终日望归程。"]},{"t":"诗礼堂为衍圣公赋","f":"五言律诗","c":["洙泗趍庭日，相传自世家。","三千惟有敬，一语自无邪。","乔木参天色，猗兰绕砌花。","遗风从此地，花雨被无涯。"]},{"t":"崇恩堂为衍圣公赋","f":"五言律诗","c":["赤芾趍朝日，彤庭锡劳时。","宫壶沾宠渥，命服被恩私。","遗泽应无竭，深恩勉自持。","高台书盛事，行见被声诗。"]},{"t":"题风木卷","f":"五言律诗","c":["秋色满天地，寸心将若何。","行云宁返迹，逝水绝回波。","断织封蛛网，残篇掩蓼莪。","空馀东岭树，向夕受风多。"]},{"t":"题瞻云卷","f":"五言律诗","c":["游子久行役，松楸空系情。","几经秋草合，长见白云生。","水映遥空淡，烟迷暮垄平。","鹤归华表夜，沧海月虚明。"]},{"t":"人日立春","f":"五言律诗","c":["人日逢春日，韶华此又新。","暂归持斧客，犹是读书人。","别久交游敬，年深骨肉亲。","升平占霁景，爱国赋诗频。"]},{"t":"村居","f":"五言律诗","c":["乔木荒村古，归来遂所居。","人情安瓦落，机事识舟虚。","岁晚霜横野，宵长月照书。","心田恐芜没，不敢废耘锄。"]},{"t":"读书","f":"五言律诗","c":["俯仰千年道，常看万卷书。","鬓毛兼黑白，事业尚铅朱。","庭雨催寒早，窗风度月虚。","抚时宁浪出，慨想北溟鱼。"]},{"t":"中秋夜诸生持酒至二首 其一","f":"五言律诗","c":["宪府乘骢入，湖南仗斧游。","异乡饶节序，故里忽中秋。","白月当空度，明河入夜流。","诸生劳载酒，坚坐看相酬。"]},{"t":"中秋夜诸生持酒至二首 其二","f":"五言律诗","c":["五见中秋节，湘南想北州。","忽看今夜月，忘却昔年愁。","汾水通河汉，龙门近斗牛。","霜钟传永夕，高咏未能休。"]},{"t":"示弟瑭","f":"五言律诗","c":["大屋星霜久，新年雨雪频。","田园知己薄，生计可忘勤。","乔木宜思祖，鸡豚莫恼邻。","东堂花几树，应与岁俱春。"]},{"t":"闻张侍御升大理卿复升都御史","f":"五言律诗","c":["闻道张公子，频年被宠光。","一清廷尉法，再肃柏台霜。","绝足风云阔，高门岁月长。","所期崇令德，汗简看垂芳。"]},{"t":"夏夜","f":"五言律诗","c":["肃肃凉景夕，满怀诗思生。","虫鸣新雨霁，钟递晚风清。","爽气浮天极，乡心对月明。","中州知久客，归兴绕汾亭。"]},{"t":"挽吴孺人","f":"五言律诗","c":["高节知谁似，终身不二天。","脩篁秋更绿，老柏苦尤坚。","意切和熊处，心伤断织前。","贤郎今有立，紫诰贲幽泉。"]},{"t":"直沽舟中","f":"五言律诗","c":["潮来两岸平，风顺一帆轻。","海阔浮云白，天低野树青。","久叨持斧客，非是弃繻生。","岱岳行看近，秋高试一登。"]},{"t":"按部出济南","f":"五言律诗","c":["雨歇西门道，微凉草树秋。","风云连北极，海岳接东州。","圣世方全盛，书生得壮游。","频年叨宠渥，感激未能休。"]},{"t":"七夕宿郯城","f":"五言律诗","c":["郯子国中宿，高堂蜡炬红。","满林惊夜鹊，绕砌响秋蛩。","远意知谁省，长吟未许同。","去年当此夕，京国见西风。"]},{"t":"发长清","f":"五言律诗","c":["清晓出南郭，南行喜有山。","入林秋雾薄，到面水风寒。","已觉年华大，还应宇宙宽。","几回持宪节，不改铁为冠。"]},{"t":"卢主事具庆堂","f":"五言律诗","c":["卢子古名族，几年家大梁。","未为观国士，已作奉亲堂。","乔木侵檐密，芳花绕户香。","春风长满座，永日但称觞。"]},{"t":"登州抵福山道中二首 其一","f":"五言律诗","c":["冈岭高还下，荒村断复连。","波涛风捲雪，岛屿日生烟。","水坼人间境，春融世外天。","云霞今古异，何处有神仙。"]},{"t":"登州抵福山道中二首 其二","f":"五言律诗","c":["正是春光好，重来海上行。","轻鸥联影落，旅雁一行鸣。","徐市三山棹，安期万古名。","只今俱泯没，惟见水云平。"]},{"t":"潞河舟中","f":"五言律诗","c":["岁月忽如昨，三年又此来。","水长通御苑，山近绕金台。","谬拟传心学，惭无济世才。","永怀清不寐，终夕望三台。"]},{"t":"舟中思亲","f":"五言律诗","c":["三十年前事，舟中忽有思。","老亲游宦日，巴蜀泛江时。","青嶂两边合，黄猿万树垂。","只今行海岱，忍自受恩私。"]},{"t":"沧州舟中","f":"五言律诗","c":["澶漫沧州北，舟行逆水迟。","连林秋柳瘦，接翅晚鸦稀。","原野波涛减，人家生理微。","端居对明烛，深念莫相违。"]},{"t":"病齿","f":"五言律诗","c":["病齿经时久，忧烦屡搅肠。","吟哦良觉废，诵读总相妨。","志切风雷益，心惩噬嗑刚。","古柔无所苦，因悟养生方。"]},{"t":"赐纱","f":"五言律诗","c":["理寺承恩召，宫纱被宠光。","红酣升海日，浓染自天香。","省德知轻重，裁衣称短长。","章身良自愧，何以报皇唐。"]},{"t":"赐扇","f":"五言律诗","c":["敕赐端阳扇，云笺五色花。","动摇烦暑退，披拂好风斜。","法语真堪畏，汤铭恐未加。","身心蒙帝力，留与子孙誇。"]},{"t":"登南坡","f":"五言律诗","c":["雨霁陟岧峣，凉风作阵飘。","目随青嶂远，心与白云高。","野草连冈细，家林百尺乔。","茫茫天宇内，倦鸟已安巢。"]},{"t":"汉江源","f":"五言律诗","c":["巨峡自天辟，峨峨嶓冢尊。","回环幽谷底，清浅汉江源。","泉古通元气，根深彻后坤。","朝宗东去意，应不废晨昏。"]},{"t":"嘉陵泛江","f":"五言律诗","c":["湛湛嘉陵水，沉沉石底明。","岸翻云树影，谷响棹歌声。","微冷南风细，轻阴暮雨晴。","应难逢此景，还慰远游情。"]},{"t":"嘉陵江雨","f":"五言律诗","c":["官舫泛嘉陵，浑如一叶轻。","滩高骇浪急，岸阔漫流停。","山木无边翠，人烟几处青。","棹歌高枕听，竟日雨冥冥。"]},{"t":"雨后宿嘉陵","f":"五言律诗","c":["夜宿嘉陵岸，扁舟雨不休。","山云迷涧壑，林火射江流。","久坐思王事，难眠动旅愁。","所期氛祲扫，走马上神州。"]},{"t":"嘉陵喜晴","f":"五言律诗","c":["不堪篷背雨，直打到天明。","乍喜朝云敛，俄看旭日晴。","林分千嶂秀，山空一江清。","泛泛情何极，舟人急橹声。"]},{"t":"锦城寓馆八首 其一","f":"五言律诗","c":["寓馆富花竹，书斋夏日长。","芭蕉红锦秀，栀子白花香。","树密宁知暑，窗开但觉凉。","远怀虽暂遣，世虑未能忘。"]},{"t":"锦城寓馆八首 其二","f":"五言律诗","c":["曲径通幽处，交阴翠竹高。","书斋成雅趣，花圃惬游遨。","石甃涵天影，风林作海涛。","宁知城市内，清境胜江皋。"]},{"t":"锦城寓馆八首 其三","f":"五言律诗","c":["细雨过空庭，纤纤草色青。","凉风生近户，淡霭散高冥。","林外鹃声急，檐前燕语轻。","锦城虽可乐，终是念归程。"]},{"t":"锦城寓馆八首 其四","f":"五言律诗","c":["当户海榴树，纷纷落绛英。","竹林新笋出，石砌绿苔生。","小屋知心静，繁花觉眼明。","少陵今远矣，谁与论诗情。"]},{"t":"锦城寓馆八首 其五","f":"五言律诗","c":["偶居锦城馆，还似浣花堂。","雨过青苔润，风来翠簟凉。","竹鸣潇洒韵，花送自然香。","清兴虽无尽，乡心未可忘。"]},{"t":"锦城寓馆八首 其六","f":"五言律诗","c":["红芳经雨重，翠竹引风多。","生意每如此，天心奈乐何。","一杯吾自劝，隔户鸟当歌。","忽起乡关念，条山绕大河。"]},{"t":"锦城寓馆八首 其七","f":"五言律诗","c":["清晨坐书閤，初日照花林。","宿露泫庭竹，晴天啭野禽。","心无一念杂，窗绝半尘侵。","道理无边在，悠然思转深。"]},{"t":"锦城寓馆八首 其八","f":"五言律诗","c":["閒坐竹林内，风来见箨飘。","轻烟晴冉冉，凉气晚萧萧。","易古还宗邵，书删却自尧。","莫嫌耽典籍，清景美相调。"]},{"t":"有感五首 其一","f":"五言律诗","c":["火发木将燬，奸生理自危。","洞观千古事，深合一时为。","往事既如此，来踪可更追。","尔心徒自省，吾道欲何之。"]},{"t":"有感五首 其二","f":"五言律诗","c":["谁使三苗叛，深劳王者师。","操兵诸将勇，转粟万人疲。","行见投戈日，还看奏凯时。","犬狼何足道，雨露本无私。"]},{"t":"有感五首 其三","f":"五言律诗","c":["锦里南天外，中原北斗边。","乘轺孤节远，恋阙寸心悬。","雁塞氛常净，龙沙驾已旋。","忠臣扶社稷，快著祖生鞭。"]},{"t":"有感五首 其四","f":"五言律诗","c":["庶官务割剥，不念远人穷。","况复羽书急，时兼馈饷供。","探兵林莽密，转粟水山重。","指日兵氛扫，车书四海同。"]},{"t":"有感五首 其五","f":"五言律诗","c":["禁闼知无补，江山敢惮劳。","运粮民力困，讨贼将心骄。","围解人饥死，蛮穷县劫烧。","贪官能致乱，选牧望天朝。"]},{"t":"锦城馆杂题十三首 其一 竹","f":"五言律诗","c":["谁种庭前竹，萧森数十竿。","高檐晴落翠，虚室昼生寒。","韵喜风前听，阴宜月下看。","莫言家在远，长得报平安。"]},{"t":"锦城馆杂题十三首 其二 榴","f":"五言律诗","c":["细叶枝枝翠，娇英朵朵红。","爱看房有实，不信色为空。","迎夏葵争发，倾阳意略同。","因之思汉武，花满近郊浓。"]},{"t":"锦城馆杂题十三首 其三 芭蕉","f":"五言律诗","c":["弱植亭亭立，新枝渐渐开。","自能承雨露，元不愧尘埃。","蕊艳抽红锦，阴长落翠苔。","新诗题满叶，秋意莫先来。"]},{"t":"锦城馆杂题十三首 其四 木瓜","f":"五言律诗","c":["窗外有奇树，木瓜枝相交。","幸自少酸味，何由动老饕。","香气颇幽馥，鸟声恒寂寥。","莫为相好赠，却恐报琼瑶。"]},{"t":"锦城馆杂题十三首 其五 棕树","f":"五言律诗","c":["小圃高棕树，亭亭迥出云。","近身皮尽古，到顶叶才分。","性直钟元气，根多托厚坤。","幸兹无剥削，生意得长存。"]}]};